",border:`1px solid ${showIv?t.accent+\"44\":\"#222\"}`,background:\"transparent\",color:showIv?t.accent:\"#aaa\",cursor:\"pointer\",borderRadius:2,fontSize:\"10px\",fontFamily:\"inherit\",letterSpacing:1,whiteSpace:\"nowrap\"}}>INTERVALS {showIv?\"ON\":\"OFF\"}</button>\n              <button onClick={()=>setPremium(true)} style={{padding:\"2px 8px\",border:\"1px solid #333\",background:\"transparent\",color:\"#888\",cursor:\"pointer\",borderRadius:2,fontSize:\"10px\",fontFamily:\"inherit\",letterSpacing:1,whiteSpace:\"nowrap\",display:\"flex\",alignItems:\"center\",gap:4}}>CAGED BOXES</button>\n              <button onClick={()=>setPremium(true)} style={{padding:\"2px 8px\",border:\"1px solid #333\",background:\"transparent\",color:\"#888\",cursor:\"pointer\",borderRadius:2,fontSize:\"10px\",fontFamily:\"inherit\",letterSpacing:1,whiteSpace:\"nowrap\",display:\"flex\",alignItems:\"center\",gap:4}}>CHORD MAP</button>\n              <div style={{width:\"100%\",height:1,background:\"#1a1a1a\",margin:\"1px 0\"}}/>\n              <button onClick={()=>setNV(v=>v===\"all\"?null:\"all\")} style={{padding:\"2px 8px\",border:`1px solid ${noteView===\"all\"?t.natFg+\"44\":\"#222\"}`,background:noteView===\"all\"?t.natBg:\"transparent\",color:noteView===\"all\"?t.natFg:\"#aaa\",cursor:\"pointer\",borderRadius:2,fontSize:\"10px\",fontFamily:\"inherit\",letterSpacing:1,whiteSpace:\"nowrap\"}}>ALL NOTES</button>\n              <button onClick={()=>setNV(v=>v===\"natural\"?null:\"natural\")} style={{padding:\"2px 8px\",border:`1px solid ${noteView===\"natural\"?t.natFg+\"44\":\"#222\"}`,background:noteView===\"natural\"?t.natBg:\"transparent\",color:noteView===\"natural\"?t.natFg:\"#aaa\",cursor:\"pointer\",borderRadius:2,fontSize:\"10px\",fontFamily:\"inherit\",letterSpacing:1,whiteSpace:\"nowrap\"}}>NATURALS</button>\n              <button onClick={()=>setNV(v=>v===\"bare\"?null:\"bare\")} style={{padding:\"2px 8px\",border:`1px solid ${noteView===\"bare\"?\"#55555544\":\"#222\"}`,background:noteView===\"bare\"?\"#111\":\"transparent\",color:noteView===\"bare\"?\"#bbb\":\"#aaa\",cursor:\"pointer\",borderRadius:2,fontSize:\"10px\",fontFamily:\"inherit\",letterSpacing:1,whiteSpace:\"nowrap\"}}>BARE</button>\n            </div>\n          </div>\n        </div>\n      )}\n\n      {(tab===\"scale\"||tab===\"copilot\")&&(\n        <div style={{padding:\"3px 20px\",fontSize:\"10px\",color:\"#bbb\",letterSpacing:\"0.8px\",flexShrink:0,display:\"flex\",justifyContent:\"space-between\",fontFamily:\"system-ui,-apple-system,sans-serif\"}}>\n          <span>← scroll for full 24-fret neck · O = open · gold bar = NUT</span>\n          {tab===\"copilot\" && activeChord && <span style={{color:t.accent, fontWeight:700}}>CHORD VIEW: {activeChord.name} ({showIv ? \"INTERVALS\" : \"FINGERINGS\"})</span>}\n          {tab===\"scale\" && noteView===\"all\"&&<span style={{color:\"#6aaa6a\"}}>ALL NOTES — gold=root · green=natural · blue=sharp/flat</span>}\n          {tab===\"scale\" && noteView===\"natural\"&&<span style={{color:\"#6aaa6a\"}}>NATURALS — A B C D E F G only · gold=root</span>}\n          {tab===\"scale\" && noteView===\"bare\"&&<span style={{color:\"#777\"}}>BARE — fretboard only</span>}\n        </div>\n      )}\n\n      <div style={{overflow:\"auto\"}}>\n        {(tab===\"scale\"||tab===\"copilot\")&&(\n          <div style={{overflowX:\"auto\",padding:\"4px 20px 6px\"}}>\n            <div style={{minWidth:(NUM_FRETS+1)*FW+44,position:\"relative\"}}>\n              <div style={{display:\"flex\",paddingLeft:40,marginBottom:3}}>\n                {Array.from({length:NUM_FRETS+1},(_,f)=>(\n                  <div key={f} style={{width:FW,flexShrink:0,textAlign:\"center\",fontSize:\"10px\",color:DOT.has(f)?\"#c8b87a\":\"#ccc\",fontWeight:DOT.has(f)?700:400}}>{f===0?\"○\":f}</div>\n                ))}\n              </div>\n              {OPEN.map((_,si)=>(\n                <div key={si} style={{display:\"flex\",alignItems:\"center\",height:SH}}>\n                  <div style={{width:40,fontSize:\"12px\",color:\"#ddd\",textAlign:\"right\",paddingRight:8,flexShrink:0,letterSpacing:1}}>{SNAMES[si]}</div>\n                  {Array.from({length:NUM_FRETS+1},(_,fret)=>{\n                    const {bg,fg,ring,size,shape,label}=getDotStyle(si,fret);\n                    const br=shape===\"square\"?3:size/2;\n                    return (\n                      <div key={fret} style={{width:FW,height:SH,flexShrink:0,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",position:\"relative\",borderRight:fret===0?`2px solid #c8b87a45`:\"1px solid #161616\"}}>\n                        {fret>0&&<div style={{position:\"absolute\",left:0,right:0,height:0.6+si*0.22,background:`hsl(0,0%,${10+si*1.4}%)`,zIndex:0}}/>}\n                        <div style={{width:size,height:size,borderRadius:br,zIndex:2,position:\"relative\",background:bg,color:fg,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",fontSize:label&&label.length>2?\"6px\":label?.includes(\"#\")?\"7px\":\"9px\",fontWeight:700,border:ring,boxSizing:\"border-box\",fontFamily:\"inherit\",overflow:\"hidden\"}}>\n                          {fg!==\"transparent\"?label:\"\"}\n                        </div>\n                      </div>\n                    );\n                  })}\n                </div>\n              ))}\n              {[3,5,7,9,12,15,17,19,21,24].flatMap(f=>{\n                const x=40+f*FW+FW/2-3,isDbl=f===12||f===24;\n                const ds=top=>({position:\"absolute\",left:x,top,width:6,height:6,borderRadius:3,background:\"#282828\",zIndex:4,pointerEvents:\"none\"});\n                return isDbl?[<div key={`a${f}`} style={ds(90)}/>,<div key={`b${f}`} style={ds(170)}/>]:[<div key={f} style={ds(130)}/>];\n              })}\n            </div>\n          </div>\n        )}\n      </div>\n\n      {tab===\"scale\"&&(\n        <>\n          <div style={{borderTop:\"1px solid #141414\",padding:\"7px 20px\",display:\"flex\",gap:10,alignItems:\"flex-start\",background:\"#080808\",flexShrink:0,minHeight:36}}>\n            <div style={{fontSize:\"10px\",color:\"#ccc\",letterSpacing:2,paddingTop:2,flexShrink:0,fontFamily:\"'Courier New',monospace\",minWidth:40}}>COACH</div>\n            <div style={{fontSize:\"13px\",color:\"#e0dcd0\",lineHeight:1.6,fontStyle:\"italic\",fontFamily:\"system-ui,-apple-system,sans-serif\"}}>{coachText}</div>\n          </div>\n\n          <WaitlistStrip accent={t.accent}/>\n\n          <div style={{borderTop:\"1px solid #141414\",padding:\"8px 20px\",background:\"#080808\",flexShrink:0,display:\"flex\",justifyContent:\"space-between\",alignItems:\"center\"}}>\n            <div><span style={{fontSize:\"10px\",color:\"#aaa\",letterSpacing:2,fontFamily:\"'Courier New',monospace\"}}>TRAINER TIP </span><span style={{fontSize:\"10px\",color:\"#888\",fontFamily:\"system-ui,-apple-system,sans-serif\"}}>· AI-powered</span></div>\n            <button onClick={()=>setPremium(true)} style={{padding:\"3px 10px\",borderRadius:20,border:`1px solid ${t.accent}55`,background:\"transparent\",color:t.accent,cursor:\"pointer\",fontSize:\"11px\",fontFamily:\"'Courier New',monospace\",letterSpacing:\"0.5px\"}}>🔒 Unlock tips</button>\n          </div>\n\n          <div style={{background:\"#060606\",borderTop:\"1px solid #181818\",padding:\"6px 12px 8px\",flexShrink:0}}>\n            <div style={{display:\"flex\",gap:3,flexWrap:\"wrap\",marginBottom:5}}>\n              {[`Explain CAGED for ${root}`,`${root} ${scale||\"Pentatonic Minor\"} lick ideas`,\"Chord tones vs passing tones\",\"Connect the 5 boxes\"].map((p,i)=>(\n                <button key={i} onClick={()=>setPremium(true)} style={{padding:\"2px 7px\",border:\"1px solid #333\",borderRadius:2,background:\"transparent\",color:\"#999\",cursor:\"pointer\",fontSize:\"10px\",fontFamily:\"system-ui,-apple-system,sans-serif\",letterSpacing:\"0.3px\",whiteSpace:\"nowrap\"}}>{p}</button>\n              ))}\n            </div>\n            <div style={{display:\"flex\",gap:7,alignItems:\"center\"}}>\n              <div onClick={()=>setPremium(true)} style={{flex:1,background:\"#0e0e0e\",border:\"1px solid #2a2a2a\",borderRadius:2,color:\"#999\",padding:\"7px 13px\",fontSize:13,cursor:\"pointer\",fontFamily:\"system-ui,-apple-system,sans-serif\",userSelect:\"none\"}}>\n                Ask the coach about {root} {scale||\"scales\"}...\n              </div>\n              <button onClick={()=>setPremium(true)} style={{padding:\"7px 13px\",borderRadius:2,border:`1px solid ${t.accent}55`,cursor:\"pointer\",background:\"transparent\",color:t.accent,fontSize:\"11px\",fontWeight:700,fontFamily:\"inherit\",letterSpacing:1,flexShrink:0}}>🔒 ASK</button>\n            </div>\n          </div>\n        </>\n      )}\n\n      {tab===\"copilot\"&&(\n        <div className=\"workspace-split\" style={{borderTop:\"1px solid #141414\"}}>\n          {/* Left Panel: Search & Select */}\n          <div className=\"left-panel\">\n            <div>\n              <div style={{fontSize:\"11px\",color:\"#ddd\",letterSpacing:2,marginBottom:8,fontWeight:700,fontFamily:\"'Courier New',monospace\"}}>SEARCH SONG</div>\n              <div style={{position:\"relative\"}}>\n                <input \n                  type=\"text\" \n                  value={searchQuery}\n                  onChange={(e)=>setSearchQuery(e.target.value)}\n                  onKeyDown={(e)=>{\n                    if (e.key === \"Enter\" && searchQuery.trim()) {\n                      handleSearch(searchQuery.trim());\n                    }\n                  }}\n                  placeholder=\"e.g. Purple Rain, Sultans...\"\n                  style={{width:\"100%\",background:\"#0d0d0d\",border:\"1px solid #2a2a2a\",borderRadius:4,color:\"#bbb\",padding:\"8px 12px\",fontSize:\"12px\",fontFamily:\"inherit\",outline:\"none\"}}\n                />\n                <button \n                  onClick={()=>searchQuery.trim() && handleSearch(searchQuery.trim())}\n                  style={{position:\"absolute\",right:8,top:6,background:\"none\",border:\"none\",color:t.accent,fontSize:\"12px\",cursor:\"pointer\",fontWeight:700,fontFamily:\"'Courier New',monospace\"}}\n                >\n                  GO\n                </button>\n              </div>\n            </div>\n\n            {searching && (\n              <div style={{padding:\"14px\",background:\"rgba(255,255,255,0.02)\",border:\"1px solid rgba(255,255,255,0.05)\",borderRadius:6,textAlign:\"center\"}}>\n                <div style={{fontSize:\"18px\",marginBottom:6}}>⚡</div>\n                <div style={{fontSize:\"11px\",color:t.accent,fontFamily:\"'Courier New',monospace\",letterSpacing:1}}>{searchLoadingText}</div>\n              </div>\n            )}\n\n            {searchStatus === \"waitlist\" && (\n              <div style={{padding:\"14px\",background:\"rgba(200,184,122,0.04)\",border:`1px solid ${t.accent}33`,borderRadius:6}}>\n                <div style={{fontSize:\"12px\",fontWeight:700,color:\"#e8e0d0\",marginBottom:6}}>Song Waitlisted</div>\n                <p style={{fontSize:\"11px\",color:\"#aaa\",lineHeight:1.5,fontFamily:\"system-ui,-apple-system,sans-serif\",marginBottom:10}}>\n                  We are indexing and mapping the fretboard harmonics for <strong>\"{searchQuery}\"</strong>. Join the waitlist to get notified when the AI finishes analysis!\n                </p>\n                <button \n                  onClick={()=>setPremium(true)}\n                  style={{width:\"100%\",padding:\"6px 12px\",background:t.accent,border:\"none\",borderRadius:4,color:\"#111\",fontSize:\"10px\",fontWeight:700,cursor:\"pointer\",fontFamily:\"'Courier New',monospace\"}}\n                >\n                  🚀 JOIN WAITLIST\n                </button>\n              </div>\n            )}\n\n            <div>\n              <div style={{fontSize:\"11px\",color:\"#ddd\",letterSpacing:2,marginBottom:8,fontWeight:700,fontFamily:\"'Courier New',monospace\"}}>FEATURED DEMOS</div>\n              <div style={{display:\"flex\",flexDirection:\"column\",gap:8}}>\n                {FEATURED_SONGS.map(song=>(\n                  <div \n                    key={song.title} \n                    onClick={()=>{\n                      setSelectedSong(song);\n                      setRoot(song.key);\n                      setSc(song.scaleName);\n                      setActiveChord(null);\n                      setSearchStatus(\"idle\");\n                      setChatHistory([\n                        { sender: \"coach\", text: `Hey! I'm your Song Copilot. Let's break down ${song.title} by ${song.artist}. Ask me anything about the chords, scales, or techniques!` }\n                      ]);\n                    }}\n                    style={{\n                      padding:\"12px 14px\",\n                      background:selectedSong?.title===song.title?\"rgba(255,255,255,0.03)\":\"#101010\",\n                      border:`1px solid ${selectedSong?.title===song.title?t.accent+\"66\":\"#1c1c1c\"}`,\n                      borderRadius:6,\n                      cursor:\"pointer\",\n                      transition:\"border-color 0.2s\"\n                    }}\n                  >\n                    <div style={{fontSize:\"13px\",fontWeight:700,color:\"#e8e0d0\"}}>{song.title}</div>\n                    <div style={{fontSize:\"11px\",color:\"#888\",marginTop:2}}>{song.artist}</div>\n                    <div style={{display:\"flex\",gap:4,marginTop:6}}>\n                      <span style={{fontSize:\"9px\",background:\"#1b1b1b\",padding:\"2px 6px\",borderRadius:4,color:\"#ccc\"}}>{song.key} {song.scaleName}</span>\n                    </div>\n                  </div>\n                ))}\n              </div>\n            </div>\n\n            <div style={{marginTop:\"auto\",padding:\"10px\",background:\"rgba(255,255,255,0.01)\",borderRadius:6,border:\"1px solid #1a1a1a\"}}>\n              <div style={{fontSize:\"10px\",color:t.accent,letterSpacing:1,fontWeight:700,marginBottom:4,fontFamily:\"'Courier New',monospace\"}}>COPILOT TIP</div>\n              <p style={{fontSize:\"10px\",color:\"#888\",lineHeight:1.4,fontFamily:\"system-ui,-apple-system,sans-serif\"}}>\n                Click chord buttons in the workspace to highlight shapes. Toggle <strong>INTERVALS ON</strong> above to see chord scale functions.\n              </p>\n            </div>\n          </div>\n\n          {/* Right Panel: Deconstruction Workspace */}\n          <div className=\"right-panel\">\n            {selectedSong && (\n              <>\n                <div style={{borderBottom:\"1px solid #1c1c1c\",paddingBottom:12}}>\n                  <div style={{display:\"flex\",justifyContent:\"space-between\",alignItems:\"baseline\",flexWrap:\"wrap\",gap:8}}>\n                    <h2 style={{fontSize:22,fontWeight:700,color:\"#e8e0d0\"}}>{selectedSong.title}</h2>\n                    <span style={{fontSize:13,color:\"#888\"}}>by {selectedSong.artist}</span>\n                  </div>\n                  <div style={{fontSize:11,color:t.accent,fontStyle:\"italic\",marginTop:6,letterSpacing:\"0.5px\"}}>\n                    \"Knowing the notes is different from understanding how to play.\"\n                  </div>\n                </div>\n\n                {/* The Essence */}\n                <div>\n                  <div style={{fontSize:\"10px\",color:\"#888\",letterSpacing:2,fontWeight:700,marginBottom:6,fontFamily:\"'Courier New',monospace\"}}>THE ESSENCE</div>\n                  <p style={{fontSize:\"13px\",color:\"#d4c9a8\",lineHeight:1.6,fontFamily:\"system-ui,-apple-system,sans-serif\"}}>\n                    {selectedSong.essence}\n                  </p>\n                </div>\n\n                {/* The Why */}\n                <div>\n                  <div style={{fontSize:\"10px\",color:\"#888\",letterSpacing:2,fontWeight:700,marginBottom:6,fontFamily:\"'Courier New',monospace\"}}>THE THEORY (\"THE WHY\")</div>\n                  <p style={{fontSize:\"13px\",color:\"#bbb\",lineHeight:1.6,fontFamily:\"system-ui,-apple-system,sans-serif\"}}>\n                    {selectedSong.why}\n                  </p>\n                </div>\n\n                {/* Interactive Chord Overlays */}\n                <div>\n                  <div style={{fontSize:\"10px\",color:\"#888\",letterSpacing:2,fontWeight:700,marginBottom:2,fontFamily:\"'Courier New',monospace\"}}>INTERACTIVE CHORDS (Click to highlight)</div>\n                  <div className=\"chords-grid\">\n                    {selectedSong.chords.map(chord=>(\n                      <button \n                        key={chord.name}\n                        onClick={()=>{\n                          if (activeChord?.name === chord.name) {\n                            setActiveChord(null);\n                          } else {\n                            setActiveChord(chord);\n                          }\n                        }}\n                        style={{\n                          border: activeChord?.name === chord.name ? `1px solid ${t.accent}` : \"1px solid rgba(255,255,255,0.06)\",\n                          background: activeChord?.name === chord.name ? `${t.accent}12` : \"rgba(255,255,255,0.02)\",\n                          boxShadow: activeChord?.name === chord.name ? `0 0 10px ${t.accent}11` : \"none\"\n                        }}\n                        className=\"chord-btn\"\n                      >\n                        <span style={{color: activeChord?.name === chord.name ? t.accent : \"#ccc\"}}>{chord.name}</span>\n                        <span style={{fontSize:\"9px\",fontWeight:400,color:\"#666\"}}>\n                          {activeChord?.name === chord.name ? \"✓ Highlighted\" : \"Click to view\"}\n                        </span>\n                      </button>\n                    ))}\n                  </div>\n                </div>\n\n                {/* Technique Checklist */}\n                <div>\n                  <div style={{fontSize:\"10px\",color:\"#888\",letterSpacing:2,fontWeight:700,marginBottom:8,fontFamily:\"'Courier New',monospace\"}}>COACH TECHNIQUE CHECKLIST</div>\n                  <div style={{display:\"flex\",flexDirection:\"column\",gap:8}}>\n                    {selectedSong.tips.map((tip,i)=>(\n                      <div key={i} style={{display:\"flex\",gap:10,alignItems:\"flex-start\",background:\"rgba(255,255,255,0.01)\",padding:\"10px 12px\",borderRadius:6,border:\"1px solid #161616\"}}>\n                        <span style={{color:t.accent,fontWeight:700,fontFamily:\"'Courier New',monospace\"}}>0{i+1}.</span>\n                        <span style={{fontSize:\"12px\",color:\"#aaa\",lineHeight:1.5,fontFamily:\"system-ui,-apple-system,sans-serif\"}}>{tip}</span>\n                      </div>\n                    ))}\n                  </div>\n                </div>\n\n                {/* AI Copilot Chat */}\n                <div>\n                  <div style={{display:\"flex\",justifyContent:\"space-between\",alignItems:\"baseline\",marginBottom:6}}>\n                    <span style={{fontSize:\"10px\",color:\"#888\",letterSpacing:2,fontWeight:700,fontFamily:\"'Courier New',monospace\"}}>INTERACTIVE DECONSTRUCTION CHAT</span>\n                    <span style={{fontSize:\"9px\",color:\"#666\",fontFamily:\"system-ui,-apple-system,sans-serif\"}}>Powered by Fretboard AI</span>\n                  </div>\n                  <div className=\"chat-container\">\n                    <div className=\"chat-messages\" id=\"copilot-chat-box\">\n                      {chatHistory.map((msg,idx)=>(\n                        <div \n                          key={idx} \n                          className={`chat-bubble ${msg.sender}`}\n                          style={{\n                            background: msg.sender === \"user\" ? t.accent : undefined\n                          }}\n                        >\n                          {msg.text}\n                        </div>\n                      ))}\n                    </div>\n                    \n                    {/* Quick Questions */}\n                    <div style={{borderTop:\"1px solid #161616\",padding:\"8px 12px\",background:\"#080808\",display:\"flex\",gap:6,overflowX:\"auto\",flexShrink:0}}>\n                      {(selectedSong.qa || []).map((qa,i)=>(\n                        <button \n                          key={i}\n                          onClick={()=>handleQuickQuestion(qa.q, qa.a)}\n                          style={{\n                            padding:\"4px 10px\",\n                            background:\"transparent\",\n                            border:\"1px solid #333\",\n                            borderRadius:20,\n                            color:\"#999\",\n                            fontSize:\"10px\",\n                            cursor:\"pointer\",\n                            whiteSpace:\"nowrap\",\n                            fontFamily:\"system-ui,-apple-system,sans-serif\"\n                          }}\n                        >\n                          {qa.q}\n                        </button>\n                      ))}\n                    </div>\n\n                    {/* Chat Input */}\n                    <div style={{borderTop:\"1px solid #1c1c1c\",padding:6,display:\"flex\",gap:6,alignItems:\"center\",background:\"#060606\",flexShrink:0}}>\n                      <input \n                        type=\"text\"\n                        value={chatInput}\n                        onChange={(e)=>setChatInput(e.target.value)}\n                        onKeyDown={(e)=>{\n                          if (e.key === \"Enter\" && chatInput.trim()) {\n                            handleCustomQuestion(chatInput.trim());\n                          }\n                        }}\n                        placeholder={`Ask about ${selectedSong.title} scales, chords or solos...`}\n                        style={{\n                          flex:1,\n                          background:\"#0d0d0d\",\n                          border:\"1px solid #2a2a2a\",\n                          borderRadius:4,\n                          color:\"#bbb\",\n                          padding:\"6px 12px\",\n                          fontSize:\"12px\",\n                          fontFamily:\"system-ui,-apple-system,sans-serif\",\n                          outline:\"none\"\n                        }}\n                      />\n                      <button \n                        onClick={()=>chatInput.trim() && handleCustomQuestion(chatInput.trim())}\n                        style={{\n                          padding:\"6px 14px\",\n                          background:\"transparent\",\n                          border:`1px solid ${t.accent}66`,\n                          borderRadius:4,\n                          color:t.accent,\n                          fontSize:\"10px\",\n                          cursor:\"pointer\",\n                          fontWeight:700,\n                          fontFamily:\"'Courier New',monospace\"\n                        }}\n                      >\n                        SEND\n                      </button>\n                    </div>\n                  </div>\n                </div>\n              </>\n            )}\n          </div>\n        </div>\n      )}\n\n      <div style={{textAlign:\"center\",padding:\"5px 0 6px\",borderTop:\"1px solid #0e0e0e\",background:\"#080808\",display:\"flex\",justifyContent:\"center\",alignItems:\"center\",gap:12}}>\n        <a href={SITE_URL} target=\"_blank\" rel=\"noopener noreferrer\" style={{fontSize:\"11px\",color:\"#888\",textDecoration:\"none\",letterSpacing:1,fontFamily:\"'Courier New',monospace\"}}>Created by JRod</a>\n        <span style={{color:\"#555\",fontSize:\"11px\"}}>·</span>\n        <button onClick={()=>setPrivacy(true)} style={{background:\"none\",border:\"none\",cursor:\"pointer\",fontSize:\"11px\",color:\"#999\",fontFamily:\"'Courier New',monospace\",letterSpacing:1,padding:0}}>Privacy</button>\n      </div>\n    </div>\n  );\n}\n\nReactDOM.createRoot(document.getElementById('root')).render(<GuitarApp/>);\n</script>\n</body>\n</html>\n"; // Default to index
    
    if (path === '/local_copilot.html') html = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\"/>\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"/>\n  <title>Fretboard AI — Local Song Copilot</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    *{box-sizing:border-box;margin:0;padding:0}\n    body{background:#0a0a0a;font-family:'Outfit',sans-serif;color:#d4c9a8;overflow-x:hidden}\n    #root ::-webkit-scrollbar{height:6px;width:6px}\n    #root ::-webkit-scrollbar-track{background:#0a0a0a}\n    #root ::-webkit-scrollbar-thumb{background:#2a2a2a;border-radius:3px}\n    #root *{scrollbar-width:thin;scrollbar-color:#2a2a2a #0a0a0a}\n\n    /* Layout */\n    .app-container {\n      display: flex;\n      flex-direction: column;\n      min-height: 100vh;\n      background: #0a0a0a;\n    }\n    .workspace-split {\n      display: flex;\n      flex: 1;\n      flex-direction: row;\n      min-height: 0;\n      border-top: 1px solid #141414;\n    }\n    .left-panel {\n      width: 340px;\n      border-right: 1px solid #141414;\n      padding: 16px;\n      overflow-y: auto;\n      display: flex;\n      flex-direction: column;\n      gap: 16px;\n      background: #080808;\n      flex-shrink: 0;\n    }\n    .right-panel {\n      flex: 1;\n      padding: 20px;\n      overflow-y: auto;\n      background: #0c0c0c;\n      display: flex;\n      flex-direction: column;\n      gap: 20px;\n    }\n\n    /* Interactive Chords Grid */\n    .chords-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));\n      gap: 10px;\n      margin-top: 8px;\n    }\n    .chord-btn {\n      padding: 10px 12px;\n      background: rgba(255,255,255,0.02);\n      border: 1px solid rgba(255,255,255,0.06);\n      border-radius: 6px;\n      color: #ccc;\n      font-family: 'Courier New', monospace;\n      font-size: 11px;\n      font-weight: 700;\n      text-align: left;\n      cursor: pointer;\n      transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n      display: flex;\n      flex-direction: column;\n      gap: 4px;\n    }\n    .chord-btn:hover {\n      background: rgba(255,255,255,0.05);\n      transform: translateY(-2px);\n    }\n\n    /* Chat Panel */\n    .chat-container {\n      border: 1px solid #1c1c1c;\n      background: #090909;\n      border-radius: 8px;\n      display: flex;\n      flex-direction: column;\n      height: 300px;\n      overflow: hidden;\n    }\n    .chat-messages {\n      flex: 1;\n      padding: 12px;\n      overflow-y: auto;\n      display: flex;\n      flex-direction: column;\n      gap: 10px;\n    }\n    .chat-bubble {\n      padding: 8px 12px;\n      border-radius: 8px;\n      font-size: 12px;\n      line-height: 1.5;\n      max-width: 85%;\n      word-break: break-word;\n    }\n    .chat-bubble.coach {\n      background: rgba(255,255,255,0.03);\n      color: #e0dcd0;\n      align-self: flex-start;\n      border: 1px solid rgba(255,255,255,0.05);\n    }\n    .chat-bubble.user {\n      align-self: flex-end;\n      color: #111;\n    }\n    .chat-bubble.system {\n      align-self: center;\n      background: rgba(255,255,255,0.02);\n      color: #888;\n      font-size: 10px;\n      font-family: 'Courier New', monospace;\n      text-align: center;\n      border-radius: 4px;\n      padding: 6px 10px;\n      border: 1px dashed rgba(255,255,255,0.05);\n      max-width: 95%;\n    }\n\n    /* Settings Modal */\n    .modal-backdrop {\n      position: fixed;\n      inset: 0;\n      z-index: 9999;\n      background: rgba(0,0,0,0.85);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      padding: 20px;\n      backdrop-filter: blur(8px);\n    }\n    .modal-box {\n      background: rgba(12,10,8,0.98);\n      border: 1px solid #c8b87a50;\n      border-radius: 16px;\n      padding: 32px;\n      max-width: 480px;\n      width: 100%;\n      position: relative;\n    }\n\n    /* Animations */\n    @keyframes pulse-accent {\n      0% { box-shadow: 0 0 0 0 rgba(200, 184, 122, 0.4); }\n      70% { box-shadow: 0 0 0 6px rgba(200, 184, 122, 0); }\n      100% { box-shadow: 0 0 0 0 rgba(200, 184, 122, 0); }\n    }\n    .active-pulse {\n      animation: pulse-accent 2s infinite;\n    }\n\n    /* Mobile responsive layout overrides */\n    @media (max-width: 768px) {\n      .workspace-split {\n        flex-direction: column;\n        overflow-y: auto;\n      }\n      .left-panel {\n        width: 100%;\n        border-right: none;\n        border-bottom: 1px solid #141414;\n        overflow-y: visible;\n        flex-shrink: 0;\n      }\n      .right-panel {\n        width: 100%;\n        overflow-y: visible;\n      }\n    }\n  </style>\n</head>\n<body>\n<div id=\"root\"></div>\n\n<!-- React & Babel CDNs -->\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.3.1/umd/react.production.min.js\" integrity=\"sha512-QVs8Lo43F9lSuBykadDb0oSXDL/BbZ588urWVCRwSIoewQv/Ewg1f84mK3U790bZ0FfhFa1YSQUmIhG+pIRKeg==\" crossorigin=\"anonymous\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.3.1/umd/react-dom.production.min.js\" integrity=\"sha512-6a1107rTlA4gYpgHAqbwLAtxmWipBdJFcq8y5S/aTge3Bp+VAklABm2LO+Kg51vOWR9JMZq1Ovjl5tpluNpTeQ==\" crossorigin=\"anonymous\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/babel-standalone/7.23.5/babel.min.js\" integrity=\"sha512-BfcEFQ1SddlO+7JRhcagE5aEc/jc+KUtCsMGjzwkM4WHPgdHmGaYQPmW9snfgfU73cGW7+9sjdk70YErPPVi0w==\" crossorigin=\"anonymous\"></script>\n\n<script type=\"text/babel\">\nconst { useState, useEffect } = React;\n\nconst NOTES = [\"C\", \"C#\", \"D\", \"D#\", \"E\", \"F\", \"F#\", \"G\", \"G#\", \"A\", \"A#\", \"B\"];\nconst OPEN = [4, 11, 7, 2, 9, 4];\nconst SNAMES = [\"e\", \"B\", \"G\", \"D\", \"A\", \"E\"];\nconst SCALES = {\n  \"Pentatonic Minor\": [0, 3, 5, 7, 10],\n  \"Pentatonic Major\": [0, 2, 4, 7, 9],\n  \"Blues\": [0, 3, 5, 6, 7, 10],\n  \"Major\": [0, 2, 4, 5, 7, 9, 11],\n  \"Natural Minor\": [0, 2, 3, 5, 7, 8, 10],\n  \"Dorian\": [0, 2, 3, 5, 7, 9, 10],\n  \"Mixolydian\": [0, 2, 4, 5, 7, 9, 10]\n};\nconst THEMES = [\n  { id: \"ebony\", name: \"Ebony\", swatch: \"#c8b87a\", accent: \"#c8b87a\", scaleFg: \"#c0f0d4\", scaleBg: \"#0e2016\", scaleBorder: \"#1e4028\", natFg: \"#d0a850\", natBg: \"#1e1508\", sharpFg: \"#5878b8\", sharpBg: \"#0e1228\" },\n  { id: \"ocean\", name: \"Ocean\", swatch: \"#48b0e0\", accent: \"#48b0e0\", scaleFg: \"#a8dcf8\", scaleBg: \"#071428\", scaleBorder: \"#183858\", natFg: \"#7090b8\", natBg: \"#0a1220\", sharpFg: \"#405898\", sharpBg: \"#080e1c\" },\n  { id: \"ember\", name: \"Ember\", swatch: \"#e07040\", accent: \"#e07040\", scaleFg: \"#f5c890\", scaleBg: \"#1e0c04\", scaleBorder: \"#502808\", natFg: \"#c89060\", natBg: \"#1c1008\", sharpFg: \"#906040\", sharpBg: \"#140e08\" },\n  { id: \"amethyst\", name: \"Amethyst\", swatch: \"#b070e0\", accent: \"#b070e0\", scaleFg: \"#d8aafc\", scaleBg: \"#100820\", scaleBorder: \"#381858\", natFg: \"#9080c0\", natBg: \"#100c1c\", sharpFg: \"#504098\", sharpBg: \"#0c0818\" }\n];\n\nconst NUM_FRETS = 24, FW = 46, SH = 40;\nconst DOT = new Set([3, 5, 7, 9, 12, 15, 17, 19, 21, 24]);\nconst NATURALS = new Set([\"A\", \"B\", \"C\", \"D\", \"E\", \"F\", \"G\"]);\n\nconst noteAt = (si, f) => NOTES[(OPEN[si] + f) % 12];\nconst noteSet = (root, ivs) => new Set(ivs.map(i => NOTES[(NOTES.indexOf(root) + i) % 12]));\nconst IV_LABELS = [\"R\", \"b2\", \"2\", \"b3\", \"3\", \"4\", \"b5\", \"5\", \"b6\", \"6\", \"b7\", \"7\"];\nconst getInterval = (note, root) => IV_LABELS[(NOTES.indexOf(note) - NOTES.indexOf(root) + 12) % 12];\n\n// Pre-loaded high-fidelity featured songs database\nconst FEATURED_SONGS = [\n  {\n    title: \"12-Bar Blues in G\",\n    artist: \"Royalty-Free Progression\",\n    key: \"G\",\n    scaleName: \"Blues\",\n    essence: \"The foundational framework of rock and blues. This 12-bar cycle moves through the I, IV, and V chords (G7, C7, D7). By utilizing dominant 7th shapes, it creates a crunchy, soulful momentum that is perfect for pentatonic scale workouts.\",\n    why: \"Unlike simple triads, dominant 7th chords include the flat 7th interval (e.g. F in G7, Bb in C7, C in D7). This creates a dissonant 'tritone' tension that pulls naturally into the next chord. Soloing over these changes with the G Blues Scale lets you target chord tones dynamically.\",\n    tips: [\n      \"Practice slide entries: slide up a half-step into the major 3rd of the G7 chord (B) or the C7 chord (E). This is the key to that authentic blues flavor.\",\n      \"The 'blue note' is the flat 5th (Db). Use it as a passing tone when moving between the 4th (C) and 5th (D) degrees of the scale.\",\n      \"Use dominant 9th shapes for the V chord (D9) to add a modern, jazzy funk texture to your rhythm playing.\"\n    ],\n    chords: [\n      {\n        name: \"G7 (Dominant 7th)\",\n        notes: [\n          { string: 5, fret: 3, label: \"T\" },\n          { string: 3, fret: 3, label: \"1\" },\n          { string: 2, fret: 4, label: \"2\" },\n          { string: 1, fret: 3, label: \"1\" }\n        ]\n      },\n      {\n        name: \"C7 (Dominant 7th)\",\n        notes: [\n          { string: 4, fret: 3, label: \"1\" },\n          { string: 3, fret: 5, label: \"3\" },\n          { string: 2, fret: 3, label: \"1\" },\n          { string: 1, fret: 5, label: \"4\" }\n        ]\n      },\n      {\n        name: \"D9 (Funk V Chord)\",\n        notes: [\n          { string: 4, fret: 5, label: \"2\" },\n          { string: 3, fret: 4, label: \"1\" },\n          { string: 2, fret: 5, label: \"3\" },\n          { string: 1, fret: 5, label: \"4\" }\n        ]\n      }\n    ],\n    qa: [\n      {\n        q: \"What scale should I use to solo over this progression?\",\n        a: \"The most versatile choice is the G Blues Scale (G, Bb, C, Db, D, F). It works over all three dominant chords. To take it to the next level, mix the G Minor Pentatonic (dark/gritty) with the G Major Pentatonic (bright/country)—switch to Major over the G7 chord, and Minor over the C7 and D7 chords.\"\n      },\n      {\n        q: \"Why are the chords written as 7ths instead of standard major chords?\",\n        a: \"Dominant 7th chords contain both a major 3rd and a flat 7th. The interval between these two notes is a diminished fifth (tritone), which is highly unstable and tense. This tension is the core signature of the blues—it drives the progression forward, wanting to resolve to the next chord.\"\n      }\n    ]\n  },\n  {\n    title: \"Jazz ii-V-I in C\",\n    artist: \"Standard Progression\",\n    key: \"C\",\n    scaleName: \"Major\",\n    essence: \"The cornerstone of jazz harmony. This progression modulates smoothly from the ii (Dm7) to the V (G7) and resolves home to the I (Cmaj7). It is the perfect tool for practicing voice leading and modal connections across the fretboard.\",\n    why: \"The progression works because of 'guide tones'—the 3rd and 7th degrees of each chord. As the chords change, these guide tones resolve by half-steps or whole-steps, creating a seamless, rolling harmony that guides the ear home to C.\",\n    tips: [\n      \"Locate the guide tones. When moving from Dm7 to G7, the 7th of Dm7 (C) falls a half-step to become the 3rd of G7 (B). That single note change defines the chord transition.\",\n      \"Play modal scales: use D Dorian over Dm7, G Mixolydian over G7, and C Major (Ionian) over Cmaj7.\",\n      \"Use 'shell voicings' (playing only root, 3rd, and 7th) to keep your rhythm playing clean and leave space for a soloist.\"\n    ],\n    chords: [\n      {\n        name: \"D Minor 7 (ii Chord)\",\n        notes: [\n          { string: 4, fret: 5, label: \"2\" },\n          { string: 3, fret: 7, label: \"4\" },\n          { string: 2, fret: 5, label: \"1\" },\n          { string: 1, fret: 6, label: \"3\" }\n        ]\n      },\n      {\n        name: \"G7 (V Chord)\",\n        notes: [\n          { string: 5, fret: 3, label: \"T\" },\n          { string: 3, fret: 3, label: \"1\" },\n          { string: 2, fret: 4, label: \"2\" },\n          { string: 1, fret: 3, label: \"1\" }\n        ]\n      },\n      {\n        name: \"C Major 7 (I Chord)\",\n        notes: [\n          { string: 4, fret: 3, label: \"1\" },\n          { string: 3, fret: 5, label: \"3\" },\n          { string: 2, fret: 4, label: \"2\" },\n          { string: 1, fret: 5, label: \"4\" }\n        ]\n      }\n    ],\n    qa: [\n      {\n        q: \"What are 'guide tones' and how do I target them?\",\n        a: \"Guide tones are the 3rd and 7th intervals of a chord. They define whether a chord is major, minor, or dominant. In a ii-V-I progression, target these notes on the downbeat of chord changes. For example, play the note B (3rd of G7) right when the chord switches from Dm7—it sounds incredibly melodic because it resolves the previous C note by a half-step.\"\n      },\n      {\n        q: \"How does D Dorian differ from C Major if they have the same notes?\",\n        a: \"D Dorian and C Major share the exact same seven notes, but they have different 'gravitational centers'. In D Dorian, the root note is D. The minor 3rd (F) and natural 6th (B) give Dorian its distinct hopeful-minor character. Shifting the center from D to C shifts the key resolution entirely.\"\n      }\n    ]\n  },\n  {\n    title: \"House of the Rising Sun\",\n    artist: \"Traditional Folk Ballad\",\n    key: \"A\",\n    scaleName: \"Natural Minor\",\n    essence: \"A traditional folk masterpiece in 6/8 time. The progression rotates through Am, C, D, F, then resolves back to Am, E, and Am. It is a masterclass in minor-key voice leading and classical-style fingerstyle arpeggios.\",\n    why: \"The song moves from A natural minor (with a flat 7th, G) into the major V chord (E major, which uses a sharp 7th, G#). This G# note acts as the 'leading tone', pulling the harmony strongly back home to the A minor root.\",\n    tips: [\n      \"Hold down the full chord shapes and arpeggiate every string from low to high and back, letting all the notes ring out together.\",\n      \"The transition from D major to F major is tricky—use your pinky to fret the C string or target the common root shifts to make it smooth.\",\n      \"Pay attention to the 6/8 swing. Count 1-2-3-4-5-6, accenting beats 1 and 4.\"\n    ],\n    chords: [\n      {\n        name: \"A Minor\",\n        notes: [\n          { string: 4, fret: 0, label: \"O\" },\n          { string: 3, fret: 2, label: \"2\" },\n          { string: 2, fret: 2, label: \"3\" },\n          { string: 1, fret: 1, label: \"1\" }\n        ]\n      },\n      {\n        name: \"C Major\",\n        notes: [\n          { string: 4, fret: 3, label: \"3\" },\n          { string: 3, fret: 2, label: \"2\" },\n          { string: 2, fret: 0, label: \"O\" },\n          { string: 1, fret: 1, label: \"1\" }\n        ]\n      },\n      {\n        name: \"D Major\",\n        notes: [\n          { string: 3, fret: 0, label: \"O\" },\n          { string: 2, fret: 2, label: \"1\" },\n          { string: 1, fret: 3, label: \"3\" },\n          { string: 0, fret: 2, label: \"2\" }\n        ]\n      },\n      {\n        name: \"F Major (Mini Shape)\",\n        notes: [\n          { string: 3, fret: 3, label: \"3\" },\n          { string: 2, fret: 2, label: \"2\" },\n          { string: 1, fret: 1, label: \"1\" },\n          { string: 0, fret: 1, label: \"1\" }\n        ]\n      },\n      {\n        name: \"E Major (V Chord)\",\n        notes: [\n          { string: 5, fret: 0, label: \"O\" },\n          { string: 4, fret: 2, label: \"2\" },\n          { string: 3, fret: 2, label: \"3\" },\n          { string: 2, fret: 1, label: \"1\" }\n        ]\n      }\n    ],\n    qa: [\n      {\n        q: \"Why does the E major chord sound so tense compared to the minor chords?\",\n        a: \"The E major chord is the major V chord in the key of A minor. It contains the note G#, which is the 'leading tone' of the key. G# is not in the natural A minor scale (which has G natural), so it sounds surprising and tense, pulling your ear strongly upward by a half-step to resolve to the A root.\"\n      },\n      {\n        q: \"How do I play the arpeggios smoothly?\",\n        a: \"Anchor your right-hand thumb on the bass strings, and use your index (G string), middle (B string), and ring (e string) fingers to pluck the higher strings. Try not to lift your fretting hand fingers until you absolutely must change to the next chord shape.\"\n      }\n    ]\n  }\n];\n\nfunction LocalCopilotApp() {\n  const [tab, setTab] = useState(\"copilot\");\n  const [root, setRoot] = useState(\"G\");\n  const [scale, setSc] = useState(\"Blues\");\n  const [names, setNm] = useState(true);\n  const [noteView, setNV] = useState(null);\n  const [themeIdx, setTheme] = useState(0);\n  const [showIv, setIv] = useState(false);\n  \n  // Custom Song / Local API Key States\n  const [apiKey, setApiKey] = useState(() => localStorage.getItem(\"GEMINI_API_KEY\") || \"\");\n  const [showSettings, setShowSettings] = useState(false);\n  const [activeChord, setActiveChord] = useState(null);\n  const [selectedSong, setSelectedSong] = useState(FEATURED_SONGS[0]);\n  const [customSongs, setCustomSongs] = useState(() => {\n    try {\n      return JSON.parse(localStorage.getItem(\"COPILED_SONGS\")) || [];\n    } catch {\n      return [];\n    }\n  });\n\n  const [searchQuery, setSearchQuery] = useState(\"\");\n  const [searching, setSearching] = useState(false);\n  const [searchLoadingText, setSearchLoadingText] = useState(\"\");\n  const [searchError, setSearchError] = useState(\"\");\n  \n  const [chatHistory, setChatHistory] = useState([\n    { sender: \"coach\", text: \"Hey! I'm your local Song Copilot. Select a featured song, or type a song in the deconstruct bar on the left. Once you've entered your Gemini API Key in the settings (gear icon), I can deconstruct ANY song you type!\" }\n  ]);\n  const [chatInput, setChatInput] = useState(\"\");\n  const [chatLoading, setChatLoading] = useState(false);\n\n  const t = THEMES[themeIdx];\n  const ivs = scale ? (SCALES[scale] || []) : [];\n  const sNotes = noteSet(root, ivs);\n\n  // Sync song settings to fretboard key/scale\n  useEffect(() => {\n    if (selectedSong) {\n      setRoot(selectedSong.key);\n      setSc(selectedSong.scaleName);\n      setActiveChord(null);\n    }\n  }, [selectedSong]);\n\n  // Save customs\n  useEffect(() => {\n    localStorage.setItem(\"COPILED_SONGS\", JSON.stringify(customSongs));\n  }, [customSongs]);\n\n  // Fretboard highlights\n  function getDotStyle(si, fret) {\n    const note = noteAt(si, fret), inSc = sNotes.has(note), isRoot = note === root;\n    const label = showIv ? getInterval(note, root) : note;\n    let bg = \"transparent\", fg = \"transparent\", ring = \"none\", size = 24, shape = \"circle\";\n\n    if (tab === \"copilot\" && activeChord) {\n      const chordNote = activeChord.notes.find(n => n.string === si && n.fret === fret);\n      if (chordNote) {\n        const interval = getInterval(note, root);\n        const dispLabel = showIv ? interval : chordNote.label;\n        return {\n          bg: t.accent,\n          fg: \"#111\",\n          ring: `2px solid #fff`,\n          size: 26,\n          shape: \"circle\",\n          label: dispLabel\n        };\n      }\n      if (inSc) {\n        return {\n          bg: \"transparent\",\n          fg: t.scaleFg + \"30\",\n          ring: `1.5px dashed ${t.scaleBorder}44`,\n          size: 22,\n          shape: \"circle\",\n          label: showIv ? getInterval(note, root) : note\n        };\n      }\n      return { bg, fg, ring, size, shape, label: \"\" };\n    }\n\n    if (noteView === \"bare\") return { bg, fg, ring, size, shape, label };\n    if (noteView && (tab === \"scale\" || tab === \"copilot\")) {\n      const isNat = NATURALS.has(note), show = noteView === \"all\" || (noteView === \"natural\" && isNat);\n      if (show) {\n        if (isRoot) { bg = t.accent; fg = \"#111\"; size = 26; }\n        else if (isNat) { bg = t.natBg; fg = t.natFg; ring = `1px solid ${t.natFg}60`; size = 24; }\n        else { bg = t.sharpBg; fg = t.sharpFg; ring = `1px solid ${t.sharpFg}50`; size = 22; }\n      }\n      return { bg, fg, ring, size, shape, label };\n    }\n    if (tab === \"scale\" || tab === \"copilot\") {\n      if (isRoot) { bg = t.accent; fg = \"#111\"; size = 24; }\n      else if (inSc) { bg = t.scaleBg; fg = t.scaleFg; ring = `1px solid ${t.scaleBorder}`; }\n      else if (names) { fg = \"#252525\"; }\n    }\n    return { bg, fg, ring, size, shape, label };\n  }\n\n  // Deconstruct a song using Gemini API\n  async function deconstructSong(query) {\n    if (!apiKey.trim()) {\n      setSearchError(\"Please configure your Gemini API Key in the settings (gear icon) to deconstruct custom songs.\");\n      return;\n    }\n\n    setSearching(true);\n    setSearchError(\"\");\n    setSearchLoadingText(\"Connecting to Gemini...\");\n\n    const cycleTexts = [\n      \"Contacting Google model...\",\n      \"Analyzing song key and scale...\",\n      \"Extracting chord fingerings...\",\n      \"Fretting Mayer-style thumb positions...\",\n      \"Resolving CAGED fretboard intervals...\",\n      \"Finalizing structured deconstruction...\"\n    ];\n    let cycleIdx = 0;\n    const interval = setInterval(() => {\n      if (cycleIdx < cycleTexts.length) {\n        setSearchLoadingText(cycleTexts[cycleIdx++]);\n      }\n    }, 1500);\n\n    try {\n      const cleanQuery = query.replace(/[^\\w\\s-]/g, \"\");\n      const systemPrompt = `You are a professional music theorist and guitar coach. Analyze the song: \"${cleanQuery}\".\nYou must output a single JSON object. Ensure all strings (0 to 5) and frets (0 to 24) are strictly integers and physically correct for guitar standard tuning (E A D G B e).\n\nFretboard index requirements:\n- \"string\": index 5 is Low E (lowest pitch), 4 is A, 3 is D, 2 is G, 1 is B, 0 is High e (highest pitch).\n- \"fret\": 0 for open, 1 to 24 for fret positions.\n- \"label\": single character fingering (T for thumb, 1 for index, 2 for middle, 3 for ring, 4 for pinky).\n- Provide 3-5 main chords that define the song's progression or hook.\n- \"scaleName\" must be one of: \"Pentatonic Minor\", \"Pentatonic Major\", \"Blues\", \"Major\", \"Natural Minor\", \"Dorian\", \"Mixolydian\".\n- \"key\" must be one of: \"C\", \"C#\", \"D\", \"D#\", \"E\", \"F\", \"F#\", \"G\", \"G#\", \"A\", \"A#\", \"B\".\n`;\n\n      const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${apiKey}`, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({\n          contents: [{ parts: [{ text: `Analyze this song: ${cleanQuery}` }] }],\n          systemInstruction: { parts: [{ text: systemPrompt }] },\n          generationConfig: {\n            responseMimeType: \"application/json\",\n            responseSchema: {\n              type: \"OBJECT\",\n              properties: {\n                title: { type: \"STRING\" },\n                artist: { type: \"STRING\" },\n                key: { type: \"STRING\" },\n                scaleName: { type: \"STRING\" },\n                essence: { type: \"STRING\" },\n                why: { type: \"STRING\" },\n                tips: { type: \"ARRAY\", items: { type: \"STRING\" } },\n                chords: {\n                  type: \"ARRAY\",\n                  items: {\n                    type: \"OBJECT\",\n                    properties: {\n                      name: { type: \"STRING\" },\n                      notes: {\n                        type: \"ARRAY\",\n                        items: {\n                          type: \"OBJECT\",\n                          properties: {\n                            string: { type: \"INTEGER\" },\n                            fret: { type: \"INTEGER\" },\n                            label: { type: \"STRING\" }\n                          },\n                          required: [\"string\", \"fret\", \"label\"]\n                        }\n                      }\n                    },\n                    required: [\"name\", \"notes\"]\n                  }\n                },\n                qa: {\n                  type: \"ARRAY\",\n                  items: {\n                    type: \"OBJECT\",\n                    properties: {\n                      q: { type: \"STRING\" },\n                      a: { type: \"STRING\" }\n                    },\n                    required: [\"q\", \"a\"]\n                  }\n                }\n              },\n              required: [\"title\", \"artist\", \"key\", \"scaleName\", \"essence\", \"why\", \"tips\", \"chords\", \"qa\"]\n            }\n          }\n        })\n      });\n\n      clearInterval(interval);\n      if (!response.ok) {\n        throw new Error(`Gemini API Error: Status ${response.status}`);\n      }\n\n      const result = await response.json();\n      const parsedText = result.candidates[0].content.parts[0].text;\n      const songData = JSON.parse(parsedText);\n\n      // Save custom song\n      const updatedCustoms = [songData, ...customSongs.filter(s => s.title !== songData.title)];\n      setCustomSongs(updatedCustoms);\n      setSelectedSong(songData);\n      setSearchQuery(\"\");\n      setChatHistory([\n        { sender: \"coach\", text: `I've successfully deconstructed \"${songData.title}\" by ${songData.artist}! The fretboard has been mapped. Ask me anything about this track!` }\n      ]);\n\n    } catch (err) {\n      clearInterval(interval);\n      console.error(err);\n      setSearchError(`Failed to deconstruct song. Make sure your API Key is valid and try again. Error: ${err.message}`);\n    } finally {\n      setSearching(false);\n    }\n  }\n\n  // Ask a custom question to Gemini\n  async function askCoachQuestion(questionText) {\n    if (!questionText.trim()) return;\n    setChatInput(\"\");\n    \n    const updatedHistory = [...chatHistory, { sender: \"user\", text: questionText }];\n    setChatHistory(updatedHistory);\n    scrollChat();\n\n    if (!apiKey.trim()) {\n      setTimeout(() => {\n        setChatHistory([...updatedHistory, { sender: \"system\", text: \"Configure your Gemini API Key in the settings (gear icon) to ask custom questions.\" }]);\n        scrollChat();\n      }, 600);\n      return;\n    }\n\n    setChatLoading(true);\n    try {\n      const chordsStr = selectedSong.chords.map(c => `${c.name} (string/fret notes: ${JSON.stringify(c.notes)})`).join(\", \");\n      const chatContextPrompt = `You are Fretboard AI, an expert guitar teacher helping a student play and understand the song: \"${selectedSong.title}\" by ${selectedSong.artist}.\nThe song is in the key of ${selectedSong.key} ${selectedSong.scaleName}.\nThe core essence is: ${selectedSong.essence}.\nThe theoretical background is: ${selectedSong.why}.\nThe key chords are: ${chordsStr}.\nAnswer the student's question accurately, focusing on practical fretboard execution, physical mechanics, and music theory context. Keep the answer concise (under 4-5 sentences) and clear.`;\n\n      const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${apiKey}`, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({\n          contents: [\n            { role: \"user\", parts: [{ text: `Student asks: ${questionText}` }] }\n          ],\n          systemInstruction: { parts: [{ text: chatContextPrompt }] }\n        })\n      });\n\n      if (!response.ok) throw new Error(`Status ${response.status}`);\n      \n      const result = await response.json();\n      const answer = result.candidates[0].content.parts[0].text;\n      \n      setChatHistory([...updatedHistory, { sender: \"coach\", text: answer }]);\n      scrollChat();\n    } catch (err) {\n      console.error(err);\n      setChatHistory([...updatedHistory, { sender: \"system\", text: `Chat connection failed: ${err.message}` }]);\n      scrollChat();\n    } finally {\n      setChatLoading(false);\n    }\n  }\n\n  function handleQuickQuestion(q, a) {\n    const history = [...chatHistory, { sender: \"user\", text: q }];\n    setChatHistory(history);\n    scrollChat();\n\n    setTimeout(() => {\n      setChatHistory([...history, { sender: \"coach\", text: a }]);\n      scrollChat();\n    }, 700);\n  }\n\n  function scrollChat() {\n    setTimeout(() => {\n      const box = document.getElementById(\"copilot-chat-box\");\n      if (box) box.scrollTop = box.scrollHeight;\n    }, 50);\n  }\n\n  function saveApiKey(key) {\n    setApiKey(key);\n    localStorage.setItem(\"GEMINI_API_KEY\", key);\n    setShowSettings(false);\n  }\n\n  const allSongs = [...FEATURED_SONGS, ...customSongs];\n\n  return (\n    <div className=\"app-container\">\n      {/* Settings Modal */}\n      {showSettings && (\n        <div className=\"modal-backdrop\">\n          <div className=\"modal-box\">\n            <button onClick={() => setShowSettings(false)} style={{ position: \"absolute\", top: 12, right: 14, background: \"none\", border: \"none\", cursor: \"pointer\", color: \"#555\", fontSize: 18 }}>✕</button>\n            <div style={{ textAlign: \"center\", marginBottom: 16 }}>\n              <div style={{ fontSize: 32, marginBottom: 6 }}>⚙️</div>\n              <div style={{ display: \"inline-block\", background: `${t.accent}22`, border: `1px solid ${t.accent}55`, color: t.accent, fontSize: \"9px\", letterSpacing: 2, fontWeight: 700, padding: \"3px 10px\", borderRadius: 20 }}>CONFIG LOCAL API</div>\n            </div>\n            <div style={{ fontSize: 18, fontWeight: 700, color: \"#e8e0d0\", textAlign: \"center\", marginBottom: 8 }}>Google Gemini API Key</div>\n            <p style={{ color: \"#bbb\", lineHeight: 1.6, textAlign: \"center\", marginBottom: 18, fontSize: 12 }}>\n              Paste your Gemini API Key below. This key is saved <strong>only locally</strong> in your browser's local storage and is used to request dynamic song analysis.\n            </p>\n            <form onSubmit={(e) => { e.preventDefault(); saveApiKey(e.target.elements.keyInput.value); }}>\n              <input \n                name=\"keyInput\"\n                type=\"password\" \n                defaultValue={apiKey} \n                placeholder=\"AIzaSy...\" \n                required \n                style={{ width: \"100%\", background: \"#0d0d0d\", border: \"1px solid #2a2a2a\", borderRadius: 4, color: t.accent, padding: \"10px 14px\", fontSize: \"12px\", fontFamily: \"'Courier New', monospace\", outline: \"none\", marginBottom: 12 }}\n              />\n              <button type=\"submit\" style={{ width: \"100%\", padding: \"10px\", borderRadius: 4, border: `1px solid ${t.accent}`, background: t.accent, color: \"#111\", fontSize: \"11px\", cursor: \"pointer\", fontWeight: 700, fontFamily: \"'Courier New', monospace\" }}>\n                SAVE KEY\n              </button>\n            </form>\n            <div style={{ marginTop: 12, textAlign: \"center\" }}>\n              <a href=\"https://aistudio.google.com/app/apikey\" target=\"_blank\" rel=\"noreferrer\" style={{ fontSize: \"11px\", color: \"#666\", textDecoration: \"underline\" }}>\n                Get a free Gemini API Key from Google AI Studio\n              </a>\n            </div>\n          </div>\n        </div>\n      )}\n\n      {/* Header */}\n      <div style={{ display: \"flex\", justifyContent: \"space-between\", alignItems: \"center\", padding: \"10px 20px 8px\", borderBottom: \"1px solid #181818\", flexShrink: 0 }}>\n        <div style={{ display: \"flex\", alignItems: \"baseline\", gap: 10 }}>\n          <span style={{ fontSize: 16, fontWeight: 700, color: t.accent, letterSpacing: 2 }}>FRETBOARD AI <span style={{fontSize:\"9px\", opacity:0.6}}>LOCAL</span></span>\n          <span style={{ fontSize: \"11px\", color: \"#bbb\", letterSpacing: 1, fontFamily: \"system-ui,-apple-system,sans-serif\" }}>Standard Tuning · E A D G B e</span>\n        </div>\n        <div style={{ display: \"flex\", alignItems: \"center\", gap: 8 }}>\n          <div style={{ display: \"flex\", gap: 4, alignItems: \"center\" }}>\n            {THEMES.map((th, i) => (\n              <button key={th.id} onClick={() => setTheme(i)} title={`${th.name}`} style={{ width: 14, height: 14, borderRadius: 7, border: \"none\", cursor: \"pointer\", background: th.swatch, outline: themeIdx === i ? \"2px solid #fff\" : \"2px solid transparent\", outlineOffset: 1, opacity: themeIdx === i ? 1 : 0.5 }} />\n            ))}\n            <span style={{ fontSize: \"10px\", color: \"#888\", marginLeft: 2, fontFamily: \"system-ui,-apple-system,sans-serif\" }}>{t.name}</span>\n          </div>\n          <div style={{ width: 1, height: 12, background: \"#222\" }} />\n          <button onClick={() => setShowSettings(true)} title=\"Settings\" style={{ background: \"none\", border: \"none\", cursor: \"pointer\", fontSize: 14, padding: \"2px 6px\" }}>⚙️</button>\n          <div style={{ width: 1, height: 12, background: \"#222\" }} />\n          <div style={{display:\"flex\",gap:4,alignItems:\"center\"}}>\n            <button onClick={()=>{setTab(\"scale\"); setActiveChord(null);}} style={{padding:\"4px 10px\",border:\"none\",cursor:\"pointer\",borderRadius:3,background:tab===\"scale\"?t.accent:\"transparent\",color:tab===\"scale\"?\"#111\":\"#999\",fontSize:\"11px\",fontFamily:\"inherit\",fontWeight:tab===\"scale\"?700:400}}>Scale Explorer</button>\n            <button onClick={()=>setTab(\"copilot\")} style={{padding:\"4px 10px\",border:\"none\",cursor:\"pointer\",borderRadius:3,background:tab===\"copilot\"?t.accent:\"transparent\",color:tab===\"copilot\"?\"#111\":\"#999\",fontSize:\"11px\",fontFamily:\"inherit\",fontWeight:tab===\"copilot\"?700:400,display:\"flex\",alignItems:\"center\",gap:4}}><span>🎸</span>Song Copilot</button>\n            <a href=\"/count-app/index.html\" style={{padding:\"4px 10px\",border:\"none\",cursor:\"pointer\",borderRadius:3,background:\"transparent\",color:\"#999\",fontSize:\"11px\",fontFamily:\"inherit\",fontWeight:400,textDecoration:\"none\",display:\"flex\",alignItems:\"center\",gap:4}}><span>🥁</span>Groove Box</a>\n            <a href=\"/harmony.html\" style={{padding:\"4px 10px\",border:\"none\",cursor:\"pointer\",borderRadius:3,background:\"transparent\",color:\"#999\",fontSize:\"11px\",fontFamily:\"inherit\",fontWeight:400,textDecoration:\"none\",display:\"flex\",alignItems:\"center\",gap:4}}><span>⭕</span>Harmony</a>\n          </div>\n        </div>\n      </div>\n\n      {/* Explorer Specific Settings */}\n      {tab === \"scale\" && (\n        <div style={{ padding: \"8px 20px 6px\", borderBottom: \"1px solid #141414\", flexShrink: 0 }}>\n          <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n            <div>\n              <div style={{ fontSize: \"11px\", color: \"#ddd\", letterSpacing: 2, marginBottom: 4 }}>KEY</div>\n              <div style={{ display: \"flex\", gap: 3, flexWrap: \"wrap\", maxWidth: 500 }}>\n                {NOTES.map(n => (\n                  <button key={n} onClick={() => setRoot(n)} style={{ width: 27, height: 27, borderRadius: 2, border: \"none\", cursor: \"pointer\", background: root === n ? t.accent : \"#141414\", color: root === n ? \"#111\" : \"#bbb\", fontSize: n.includes(\"#\") ? \"9px\" : \"11px\", fontWeight: root === n ? 700 : 400, fontFamily: \"inherit\" }}>{n}</button>\n                ))}\n              </div>\n            </div>\n            <div>\n              <div style={{ fontSize: \"11px\", color: \"#ddd\", letterSpacing: 2, marginBottom: 4 }}>SCALE{scale === null && <span style={{ color: \"#888\", fontWeight: 400, letterSpacing: 0, fontSize: \"10px\" }}> · none selected</span>}</div>\n              <div style={{ display: \"flex\", gap: 3, flexWrap: \"wrap\" }}>\n                {Object.keys(SCALES).map(s => (\n                  <button key={s} onClick={() => setSc(s === scale ? null : s)} style={{ padding: \"2px 8px\", border: \"none\", cursor: \"pointer\", borderRadius: 2, background: scale === s ? t.scaleBg : \"#141414\", color: scale === s ? t.scaleFg : \"#bbb\", fontSize: \"11px\", fontFamily: \"inherit\", fontWeight: scale === s ? 700 : 400, outline: scale === s ? `1px solid ${t.scaleBorder}` : \"none\" }}>{s}</button>\n                ))}\n              </div>\n            </div>\n            <div style={{ display: \"flex\", flexWrap: \"wrap\", gap: 4, alignItems: \"center\" }}>\n              <button onClick={() => setNm(x => !x)} style={{ padding: \"2px 8px\", border: `1px solid ${names ? t.accent + \"44\" : \"#222\"}`, background: \"transparent\", color: names ? t.accent : \"#aaa\", cursor: \"pointer\", borderRadius: 2, fontSize: \"10px\", fontFamily: \"inherit\", letterSpacing: 1, whiteSpace: \"nowrap\" }}>{names ? \"NAMES ON\" : \"NAMES OFF\"}</button>\n              <button onClick={() => setIv(x => !x)} style={{ padding: \"2px 8px\", border: `1px solid ${showIv ? t.accent + \"44\" : \"#222\"}`, background: \"transparent\", color: showIv ? t.accent : \"#aaa\", cursor: \"pointer\", borderRadius: 2, fontSize: \"10px\", fontFamily: \"inherit\", letterSpacing: 1, whiteSpace: \"nowrap\" }}>INTERVALS {showIv ? \"ON\" : \"OFF\"}</button>\n              <div style={{ width: \"100%\", height: 1, background: \"#1a1a1a\", margin: \"1px 0\" }} />\n              <button onClick={() => setNV(v => v === \"all\" ? null : \"all\")} style={{ padding: \"2px 8px\", border: `1px solid ${noteView === \"all\" ? t.natFg + \"44\" : \"#222\"}`, background: noteView === \"all\" ? t.natBg : \"transparent\", color: noteView === \"all\" ? t.natFg : \"#aaa\", cursor: \"pointer\", borderRadius: 2, fontSize: \"10px\", fontFamily: \"inherit\", letterSpacing: 1, whiteSpace: \"nowrap\" }}>ALL NOTES</button>\n              <button onClick={() => setNV(v => v === \"natural\" ? null : \"natural\")} style={{ padding: \"2px 8px\", border: `1px solid ${noteView === \"natural\" ? t.natFg + \"44\" : \"#222\"}`, background: noteView === \"natural\" ? t.natBg : \"transparent\", color: noteView === \"natural\" ? t.natFg : \"#aaa\", cursor: \"pointer\", borderRadius: 2, fontSize: \"10px\", fontFamily: \"inherit\", letterSpacing: 1, whiteSpace: \"nowrap\" }}>NATURALS</button>\n              <button onClick={() => setNV(v => v === \"bare\" ? null : \"bare\")} style={{ padding: \"2px 8px\", border: `1px solid ${noteView === \"bare\" ? \"#55555544\" : \"#222\"}`, background: noteView === \"bare\" ? \"#111\" : \"transparent\", color: noteView === \"bare\" ? \"#bbb\" : \"#aaa\", cursor: \"pointer\", borderRadius: 2, fontSize: \"10px\", fontFamily: \"inherit\", letterSpacing: 1, whiteSpace: \"nowrap\" }}>BARE</button>\n            </div>\n          </div>\n        </div>\n      )}\n\n      {/* Info Strip */}\n      {(tab === \"scale\" || tab === \"copilot\") && (\n        <div style={{ padding: \"3px 20px\", fontSize: \"10px\", color: \"#bbb\", letterSpacing: \"0.8px\", flexShrink: 0, display: \"flex\", justifySelf: \"space-between\", justifyContent: \"space-between\", fontFamily: \"system-ui,-apple-system,sans-serif\" }}>\n          <span>← scroll for full 24-fret neck · O = open · gold bar = NUT</span>\n          {tab === \"copilot\" && activeChord && <span style={{ color: t.accent, fontWeight: 700 }}>CHORD SHAPE: {activeChord.name} ({showIv ? \"INTERVALS\" : \"FINGERINGS\"})</span>}\n          {tab === \"scale\" && noteView === \"all\" && <span style={{ color: \"#6aaa6a\" }}>ALL NOTES — gold=root · green=natural · blue=sharp/flat</span>}\n          {tab === \"scale\" && noteView === \"natural\" && <span style={{ color: \"#6aaa6a\" }}>NATURALS — A B C D E F G only · gold=root</span>}\n          {tab === \"scale\" && noteView === \"bare\" && <span style={{ color: \"#777\" }}>BARE — fretboard only</span>}\n        </div>\n      )}\n\n      {/* Fretboard Viewport */}\n      <div style={{ overflow: \"auto\" }}>\n        {(tab === \"scale\" || tab === \"copilot\") && (\n          <div style={{ overflowX: \"auto\", padding: \"4px 20px 6px\" }}>\n            <div style={{ minWidth: (NUM_FRETS + 1) * FW + 44, position: \"relative\" }}>\n              <div style={{ display: \"flex\", paddingLeft: 40, marginBottom: 3 }}>\n                {Array.from({ length: NUM_FRETS + 1 }, (_, f) => (\n                  <div key={f} style={{ width: FW, flexShrink: 0, textAlign: \"center\", fontSize: \"10px\", color: DOT.has(f) ? \"#c8b87a\" : \"#ccc\", fontWeight: DOT.has(f) ? 700 : 400 }}>{f === 0 ? \"○\" : f}</div>\n                ))}\n              </div>\n              {OPEN.map((_, si) => (\n                <div key={si} style={{ display: \"flex\", alignItems: \"center\", height: SH }}>\n                  <div style={{ width: 40, fontSize: \"12px\", color: \"#ddd\", textAlign: \"right\", paddingRight: 8, flexShrink: 0, letterSpacing: 1 }}>{SNAMES[si]}</div>\n                  {Array.from({ length: NUM_FRETS + 1 }, (_, fret) => {\n                    const { bg, fg, ring, size, shape, label } = getDotStyle(si, fret);\n                    const br = shape === \"square\" ? 3 : size / 2;\n                    return (\n                      <div key={fret} style={{ width: FW, height: SH, flexShrink: 0, display: \"flex\", alignItems: \"center\", justifyConent: \"center\", justifyContent: \"center\", position: \"relative\", borderRight: fret === 0 ? `2px solid #c8b87a45` : \"1px solid #161616\" }}>\n                        {fret > 0 && <div style={{ position: \"absolute\", left: 0, right: 0, height: 0.6 + si * 0.22, background: `hsl(0,0%,${10 + si * 1.4}%)`, zIndex: 0 }} />}\n                        <div style={{ width: size, height: size, borderRadius: br, zIndex: 2, position: \"relative\", background: bg, color: fg, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", fontSize: label && label.length > 2 ? \"6px\" : label?.includes(\"#\") ? \"7px\" : \"9px\", fontWeight: 700, border: ring, boxSizing: \"border-box\", fontFamily: \"inherit\", overflow: \"hidden\" }}>\n                          {fg !== \"transparent\" ? label : \"\"}\n                        </div>\n                      </div>\n                    );\n                  })}\n                </div>\n              ))}\n              {[3, 5, 7, 9, 12, 15, 17, 19, 21, 24].flatMap(f => {\n                const x = 40 + f * FW + FW / 2 - 3, isDbl = f === 12 || f === 24;\n                const ds = top => ({ position: \"absolute\", left: x, top, width: 6, height: 6, borderRadius: 3, background: \"#282828\", zIndex: 4, pointerEvents: \"none\" });\n                return isDbl ? [<div key={`a${f}`} style={ds(90)} />, <div key={`b${f}`} style={ds(170)} />] : [<div key={f} style={ds(130)} />];\n              })}\n            </div>\n          </div>\n        )}\n      </div>\n\n      {/* Explorer Content Tab */}\n      {tab === \"scale\" && (\n        <div style={{ borderTop: \"1px solid #141414\", padding: \"16px 20px\", background: \"#080808\", flex: 1 }}>\n          <div style={{ fontSize: \"13px\", color: \"#e0dcd0\", lineHeight: 1.6, fontStyle: \"italic\", fontFamily: \"system-ui, sans-serif\" }}>\n            Currently in Scale Explorer mode. Select keys and scales at the top to highlight chord structures and pitch intervals across the fretboard.\n          </div>\n        </div>\n      )}\n\n      {/* Copilot Content Tab */}\n      {tab === \"copilot\" && (\n        <div className=\"workspace-split\" style={{ borderTop: \"1px solid #141414\" }}>\n          {/* Left Panel: Search & Select */}\n          <div className=\"left-panel\">\n            <div>\n              <div style={{ display: \"flex\", justifyContent: \"space-between\", alignItems: \"center\", marginBottom: 6 }}>\n                <span style={{ fontSize: \"11px\", color: \"#ddd\", letterSpacing: 2, fontWeight: 700, fontFamily: \"'Courier New', monospace\" }}>SEARCH SONG</span>\n                {!apiKey.trim() && <span onClick={() => setShowSettings(true)} style={{ fontSize: \"9px\", color: \"#9a8a50\", cursor: \"pointer\", textDecoration: \"underline\" }}>⚠️ Key Missing</span>}\n              </div>\n              <div style={{ position: \"relative\" }}>\n                <input \n                  type=\"text\" \n                  value={searchQuery}\n                  onChange={(e) => setSearchQuery(e.target.value)}\n                  onKeyDown={(e) => {\n                    if (e.key === \"Enter\" && searchQuery.trim()) {\n                      deconstructSong(searchQuery.trim());\n                    }\n                  }}\n                  placeholder=\"e.g. Hotel California, Purple Rain...\"\n                  style={{ width: \"100%\", background: \"#0d0d0d\", border: \"1px solid #2a2a2a\", borderRadius: 4, color: \"#bbb\", padding: \"8px 12px\", fontSize: \"12px\", fontFamily: \"inherit\", outline: \"none\" }}\n                />\n                <button \n                  onClick={() => searchQuery.trim() && deconstructSong(searchQuery.trim())}\n                  style={{ position: \"absolute\", right: 8, top: 6, background: \"none\", border: \"none\", color: t.accent, fontSize: \"12px\", cursor: \"pointer\", fontWeight: 700, fontFamily: \"'Courier New', monospace\" }}\n                >\n                  DECONSTRUCT\n                </button>\n              </div>\n              {searchError && (\n                <div style={{ fontSize: \"11px\", color: \"#a54545\", marginTop: 6, lineHeight: 1.4, fontFamily: \"system-ui\" }}>\n                  {searchError}\n                </div>\n              )}\n            </div>\n\n            {searching && (\n              <div style={{ padding: \"14px\", background: \"rgba(255,255,255,0.02)\", border: \"1px solid rgba(255,255,255,0.05)\", borderRadius: 6, textAlign: \"center\" }}>\n                <div style={{ fontSize: \"18px\", marginBottom: 6 }}>⚡</div>\n                <div style={{ fontSize: \"11px\", color: t.accent, fontFamily: \"'Courier New', monospace\", letterSpacing: 1 }}>{searchLoadingText}</div>\n              </div>\n            )}\n\n            <div>\n              <div style={{ fontSize: \"11px\", color: \"#ddd\", letterSpacing: 2, marginBottom: 8, fontWeight: 700, fontFamily: \"'Courier New', monospace\" }}>AVAILABLE SONGS</div>\n              <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n                {allSongs.map(song => (\n                  <div \n                    key={song.title} \n                    onClick={() => {\n                      setSelectedSong(song);\n                      setChatHistory([\n                        { sender: \"coach\", text: `Hey! Let's deconstruct ${song.title} by ${song.artist}. Click chord buttons on the right to project shapes, or ask me questions about this progression.` }\n                      ]);\n                    }}\n                    style={{\n                      padding: \"12px 14px\",\n                      background: selectedSong?.title === song.title ? \"rgba(255,255,255,0.03)\" : \"#101010\",\n                      border: `1px solid ${selectedSong?.title === song.title ? t.accent + \"66\" : \"#1c1c1c\"}`,\n                      borderRadius: 6,\n                      cursor: \"pointer\",\n                      transition: \"border-color 0.2s\"\n                    }}\n                  >\n                    <div style={{ fontSize: \"13px\", fontWeight: 700, color: \"#e8e0d0\" }}>{song.title}</div>\n                    <div style={{ fontSize: \"11px\", color: \"#888\", marginTop: 2 }}>{song.artist}</div>\n                    <div style={{ display: \"flex\", gap: 4, marginTop: 6 }}>\n                      <span style={{ fontSize: \"9px\", background: \"#1b1b1b\", padding: \"2px 6px\", borderRadius: 4, color: \"#ccc\" }}>{song.key} {song.scaleName}</span>\n                    </div>\n                  </div>\n                ))}\n              </div>\n            </div>\n\n            <div style={{ marginTop: \"auto\", padding: \"10px\", background: \"rgba(255,255,255,0.01)\", borderRadius: 6, border: \"1px solid #1a1a1a\" }}>\n              <div style={{ fontSize: \"10px\", color: t.accent, letterSpacing: 1, fontWeight: 700, marginBottom: 4, fontFamily: \"'Courier New', monospace\" }}>LOCAL INSTRUCTIONS</div>\n              <p style={{ fontSize: \"10px\", color: \"#888\", lineHeight: 1.4, fontFamily: \"system-ui,-apple-system,sans-serif\" }}>\n                Toggle <strong>INTERVALS ON</strong> at the top navbar to switch fretboard display from Fingerings (T, 1, 2, 3) to Interval Roles (R, 3, 5, 6).\n              </p>\n            </div>\n          </div>\n\n          {/* Right Panel: Deconstruction Workspace */}\n          <div className=\"right-panel\">\n            {selectedSong && (\n              <>\n                <div style={{ borderBottom: \"1px solid #1c1c1c\", paddingBottom: 12 }}>\n                  <div style={{ display: \"flex\", justifyContent: \"space-between\", alignItems: \"baseline\", flexWrap: \"wrap\", gap: 8 }}>\n                    <h2 style={{ fontSize: 22, fontWeight: 700, color: \"#e8e0d0\" }}>{selectedSong.title}</h2>\n                    <span style={{ fontSize: 13, color: \"#888\" }}>by {selectedSong.artist}</span>\n                  </div>\n                  <div style={{ fontSize: 11, color: t.accent, fontStyle: \"italic\", marginTop: 6, letterSpacing: \"0.5px\" }}>\n                    \"Knowing the notes is different from understanding how to play.\"\n                  </div>\n                </div>\n\n                {/* The Essence */}\n                <div>\n                  <div style={{ fontSize: \"10px\", color: \"#888\", letterSpacing: 2, fontWeight: 700, marginBottom: 6, fontFamily: \"'Courier New', monospace\" }}>THE ESSENCE</div>\n                  <p style={{ fontSize: \"13px\", color: \"#d4c9a8\", lineHeight: 1.6, fontFamily: \"system-ui,-apple-system,sans-serif\" }}>\n                    {selectedSong.essence}\n                  </p>\n                </div>\n\n                {/* The Why */}\n                <div>\n                  <div style={{ fontSize: \"10px\", color: \"#888\", letterSpacing: 2, fontWeight: 700, marginBottom: 6, fontFamily: \"'Courier New', monospace\" }}>THE THEORY (\"THE WHY\")</div>\n                  <p style={{ fontSize: \"13px\", color: \"#bbb\", lineHeight: 1.6, fontFamily: \"system-ui,-apple-system,sans-serif\" }}>\n                    {selectedSong.why}\n                  </p>\n                </div>\n\n                {/* Interactive Chord Overlays */}\n                <div>\n                  <div style={{ fontSize: \"10px\", color: \"#888\", letterSpacing: 2, fontWeight: 700, marginBottom: 2, fontFamily: \"'Courier New', monospace\" }}>INTERACTIVE CHORDS (Click to highlight on fretboard)</div>\n                  <div className=\"chords-grid\">\n                    {selectedSong.chords.map(chord => (\n                      <button \n                        key={chord.name}\n                        onClick={() => {\n                          if (activeChord?.name === chord.name) {\n                            setActiveChord(null);\n                          } else {\n                            setActiveChord(chord);\n                          }\n                        }}\n                        style={{\n                          border: activeChord?.name === chord.name ? `1px solid ${t.accent}` : \"1px solid rgba(255,255,255,0.06)\",\n                          background: activeChord?.name === chord.name ? `${t.accent}12` : \"rgba(255,255,255,0.02)\",\n                          boxShadow: activeChord?.name === chord.name ? `0 0 10px ${t.accent}11` : \"none\"\n                        }}\n                        className=\"chord-btn\"\n                      >\n                        <span style={{ color: activeChord?.name === chord.name ? t.accent : \"#ccc\" }}>{chord.name}</span>\n                        <span style={{ fontSize: \"9px\", fontWeight: 400, color: \"#666\" }}>\n                          {activeChord?.name === chord.name ? \"✓ Overlay Active\" : \"Click to view\"}\n                        </span>\n                      </button>\n                    ))}\n                  </div>\n                </div>\n\n                {/* Technique Checklist */}\n                <div>\n                  <div style={{ fontSize: \"10px\", color: \"#888\", letterSpacing: 2, fontWeight: 700, marginBottom: 8, fontFamily: \"'Courier New', monospace\" }}>COACH TECHNIQUE CHECKLIST</div>\n                  <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n                    {selectedSong.tips.map((tip, i) => (\n                      <div key={i} style={{ display: \"flex\", gap: 10, alignItems: \"flex-start\", background: \"rgba(255,255,255,0.01)\", padding: \"10px 12px\", borderRadius: 6, border: \"1px solid #161616\" }}>\n                        <span style={{ color: t.accent, fontWeight: 700, fontFamily: \"'Courier New', monospace\" }}>0{i+1}.</span>\n                        <span style={{ fontSize: \"12px\", color: \"#aaa\", lineHeight: 1.5, fontFamily: \"system-ui,-apple-system,sans-serif\" }}>{tip}</span>\n                      </div>\n                    ))}\n                  </div>\n                </div>\n\n                {/* AI Copilot Chat */}\n                <div>\n                  <div style={{ display: \"flex\", justifySelf: \"space-between\", justifyContent: \"space-between\", alignItems: \"baseline\", marginBottom: 6 }}>\n                    <span style={{ fontSize: \"10px\", color: \"#888\", letterSpacing: 2, fontWeight: 700, fontFamily: \"'Courier New', monospace\" }}>INTERACTIVE DECONSTRUCTION CHAT</span>\n                    <span style={{ fontSize: \"9px\", color: \"#666\", fontFamily: \"system-ui,-apple-system,sans-serif\" }}>Powered by Fretboard AI (Local API)</span>\n                  </div>\n                  <div className=\"chat-container\">\n                    <div className=\"chat-messages\" id=\"copilot-chat-box\">\n                      {chatHistory.map((msg, idx) => (\n                        <div \n                          key={idx} \n                          className={`chat-bubble ${msg.sender}`}\n                          style={{\n                            background: msg.sender === \"user\" ? t.accent : undefined\n                          }}\n                        >\n                          {msg.text}\n                        </div>\n                      ))}\n                      {chatLoading && (\n                        <div className=\"chat-bubble coach\" style={{ fontStyle: \"italic\", opacity: 0.6 }}>\n                          Coach is thinking...\n                        </div>\n                      )}\n                    </div>\n                    \n                    {/* Quick Questions */}\n                    <div style={{ borderTop: \"1px solid #161616\", padding: \"8px 12px\", background: \"#080808\", display: \"flex\", gap: 6, overflowX: \"auto\", flexShrink: 0 }}>\n                      {(selectedSong.qa || []).map((qa, i) => (\n                        <button \n                          key={i}\n                          onClick={() => handleQuickQuestion(qa.q, qa.a)}\n                          style={{\n                            padding: \"4px 10px\",\n                            background: \"transparent\",\n                            border: \"1px solid #333\",\n                            borderRadius: 20,\n                            color: \"#999\",\n                            fontSize: \"10px\",\n                            cursor: \"pointer\",\n                            whiteSpace: \"nowrap\",\n                            fontFamily: \"system-ui,-apple-system,sans-serif\"\n                          }}\n                        >\n                          {qa.q}\n                        </button>\n                      ))}\n                    </div>\n\n                    {/* Chat Input */}\n                    <div style={{ borderTop: \"1px solid #1c1c1c\", padding: 6, display: \"flex\", gap: 6, alignItems: \"center\", background: \"#060606\", flexShrink: 0 }}>\n                      <input \n                        type=\"text\"\n                        value={chatInput}\n                        onChange={(e) => setChatInput(e.target.value)}\n                        onKeyDown={(e) => {\n                          if (e.key === \"Enter\" && chatInput.trim()) {\n                            askCoachQuestion(chatInput.trim());\n                          }\n                        }}\n                        placeholder={apiKey.trim() ? `Ask about ${selectedSong.title} scales, chords or solos...` : \"⚠️ Key required to ask custom questions\"}\n                        disabled={!apiKey.trim() || chatLoading}\n                        style={{\n                          flex: 1,\n                          background: \"#0d0d0d\",\n                          border: \"1px solid #2a2a2a\",\n                          borderRadius: 4,\n                          color: \"#bbb\",\n                          padding: \"6px 12px\",\n                          fontSize: \"12px\",\n                          fontFamily: \"system-ui,-apple-system,sans-serif\",\n                          outline: \"none\"\n                        }}\n                      />\n                      <button \n                        onClick={() => chatInput.trim() && askCoachQuestion(chatInput.trim())}\n                        disabled={!apiKey.trim() || chatLoading}\n                        style={{\n                          padding: \"6px 14px\",\n                          background: \"transparent\",\n                          border: `1px solid ${t.accent}66`,\n                          borderRadius: 4,\n                          color: t.accent,\n                          fontSize: \"10px\",\n                          cursor: \"pointer\",\n                          fontWeight: 700,\n                          fontFamily: \"'Courier New', monospace\"\n                        }}\n                      >\n                        SEND\n                      </button>\n                    </div>\n                  </div>\n                </div>\n              </>\n            )}\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n\nReactDOM.createRoot(document.getElementById('root')).render(<LocalCopilotApp />);\n</script>\n</body>\n</html>\n";
    else if (path === '/landing.html') html = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\"/>\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"/>\n  <title>Fretboard AI — Coming Soon</title>\n  <style>\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n\n    :root {\n      --bg:       #080808;\n      --bg2:      #0d0d0d;\n      --bg3:      #111111;\n      --border:   #1a1a1a;\n      --gold:     #c8b87a;\n      --gold-dim: #8a7a50;\n      --text:     #d4c9a8;\n      --muted:    #666;\n      --dim:      #3a3a3a;\n      --font:     'Courier New', Courier, monospace;\n    }\n\n    html, body {\n      min-height: 100vh;\n      background: var(--bg);\n      color: var(--text);\n      font-family: var(--font);\n      -webkit-font-smoothing: antialiased;\n    }\n\n    /* ── layout ── */\n    .page {\n      max-width: 680px;\n      margin: 0 auto;\n      padding: 0 24px;\n      display: flex;\n      flex-direction: column;\n      min-height: 100vh;\n    }\n\n    /* ── header ── */\n    .header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding: 28px 0 24px;\n      border-bottom: 1px solid var(--border);\n    }\n    .logo {\n      font-size: 14px;\n      font-weight: 700;\n      letter-spacing: 3px;\n      color: var(--gold);\n    }\n    .badge {\n      font-size: 7px;\n      letter-spacing: 2px;\n      color: var(--muted);\n      border: 1px solid var(--border);\n      padding: 3px 8px;\n      border-radius: 20px;\n    }\n\n    /* ── hero ── */\n    .hero {\n      flex: 1;\n      display: flex;\n      flex-direction: column;\n      justify-content: center;\n      padding: 72px 0 48px;\n    }\n    .eyebrow {\n      font-size: 8px;\n      letter-spacing: 3px;\n      color: var(--gold-dim);\n      margin-bottom: 20px;\n    }\n    .headline {\n      font-size: clamp(26px, 5vw, 38px);\n      font-weight: 700;\n      color: var(--text);\n      line-height: 1.2;\n      letter-spacing: -0.5px;\n      margin-bottom: 18px;\n    }\n    .headline em {\n      color: var(--gold);\n      font-style: normal;\n    }\n    .subhead {\n      font-size: 13px;\n      color: var(--muted);\n      line-height: 1.8;\n      max-width: 480px;\n      margin-bottom: 44px;\n    }\n\n    /* ── form ── */\n    .form-wrap {\n      display: flex;\n      gap: 8px;\n      max-width: 440px;\n      margin-bottom: 12px;\n    }\n    .email-input {\n      flex: 1;\n      background: var(--bg2);\n      border: 1px solid var(--border);\n      border-radius: 3px;\n      color: var(--text);\n      padding: 11px 14px;\n      font-size: 11px;\n      font-family: var(--font);\n      outline: none;\n      transition: border-color 0.2s;\n    }\n    .email-input:focus { border-color: var(--gold-dim); }\n    .email-input::placeholder { color: var(--dim); }\n    .email-input.err { border-color: #6b2020; }\n\n    .cta-btn {\n      padding: 11px 20px;\n      background: var(--gold);\n      color: #111;\n      border: none;\n      border-radius: 3px;\n      font-size: 10px;\n      font-weight: 700;\n      font-family: var(--font);\n      letter-spacing: 1.5px;\n      cursor: pointer;\n      flex-shrink: 0;\n      transition: opacity 0.15s;\n    }\n    .cta-btn:hover   { opacity: 0.88; }\n    .cta-btn:disabled { opacity: 0.4; cursor: default; }\n\n    .form-note {\n      font-size: 8px;\n      color: var(--dim);\n      letter-spacing: 0.5px;\n    }\n    .form-note.success { color: var(--gold); }\n    .form-note.dupe    { color: var(--muted); }\n    .form-note.error   { color: #8b3030; }\n\n    /* ── divider ── */\n    .divider {\n      border: none;\n      border-top: 1px solid var(--border);\n      margin: 56px 0 48px;\n    }\n\n    /* ── features ── */\n    .features-label {\n      font-size: 7px;\n      letter-spacing: 3px;\n      color: var(--dim);\n      margin-bottom: 28px;\n    }\n    .features-grid {\n      display: grid;\n      grid-template-columns: 1fr 1fr;\n      gap: 16px;\n    }\n    @media (max-width: 480px) {\n      .features-grid { grid-template-columns: 1fr; }\n    }\n    .feature-card {\n      background: var(--bg2);\n      border: 1px solid var(--border);\n      border-radius: 4px;\n      padding: 18px 20px;\n      transition: border-color 0.2s;\n    }\n    .feature-card:hover { border-color: #2a2a2a; }\n    .feature-icon {\n      font-size: 18px;\n      margin-bottom: 10px;\n      display: block;\n    }\n    .feature-name {\n      font-size: 11px;\n      font-weight: 700;\n      color: var(--text);\n      letter-spacing: 0.5px;\n      margin-bottom: 6px;\n    }\n    .feature-desc {\n      font-size: 10px;\n      color: var(--muted);\n      line-height: 1.7;\n    }\n\n    /* ── fretboard teaser ── */\n    .fretboard-teaser {\n      margin: 48px 0 0;\n      padding: 20px;\n      background: var(--bg2);\n      border: 1px solid var(--border);\n      border-radius: 4px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 16px;\n    }\n    .teaser-left { flex: 1; }\n    .teaser-label {\n      font-size: 7px;\n      letter-spacing: 2px;\n      color: var(--dim);\n      margin-bottom: 6px;\n    }\n    .teaser-text {\n      font-size: 11px;\n      color: var(--muted);\n      line-height: 1.6;\n    }\n    .teaser-link {\n      font-size: 9px;\n      color: var(--gold);\n      text-decoration: none;\n      letter-spacing: 1px;\n      border: 1px solid var(--gold-dim);\n      padding: 6px 14px;\n      border-radius: 3px;\n      flex-shrink: 0;\n      transition: opacity 0.15s;\n    }\n    .teaser-link:hover { opacity: 0.75; }\n\n    /* ── footer ── */\n    .footer {\n      padding: 28px 0;\n      border-top: 1px solid var(--border);\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n    }\n    .footer-left {\n      font-size: 8px;\n      color: var(--dim);\n      letter-spacing: 0.5px;\n    }\n    .footer-right {\n      font-size: 8px;\n      color: var(--dim);\n      letter-spacing: 0.5px;\n    }\n\n    /* ── fret string decoration ── */\n    .fret-decoration {\n      display: flex;\n      gap: 2px;\n      margin-bottom: 32px;\n    }\n    .fret-string {\n      width: 1px;\n      height: 36px;\n      background: linear-gradient(to bottom, transparent, var(--border) 30%, var(--border) 70%, transparent);\n    }\n    .fret-dot {\n      width: 6px;\n      height: 6px;\n      border-radius: 50%;\n      background: var(--gold);\n      opacity: 0.4;\n      align-self: center;\n      flex-shrink: 0;\n    }\n  </style>\n</head>\n<body>\n<div class=\"page\">\n\n  <header class=\"header\">\n    <div class=\"logo\">FRETBOARD AI</div>\n    <div style=\"display: flex; gap: 16px; align-items: center;\">\n      <a href=\"/count-app/index.html\" style=\"color: var(--muted); text-decoration: none; font-size: 10px; font-family: system-ui, sans-serif; transition: color 0.2s;\" onmouseover=\"this.style.color='var(--text)'\" onmouseout=\"this.style.color='var(--muted)'\">Groove Box</a>\n      <a href=\"/local_copilot.html\" style=\"color: var(--muted); text-decoration: none; font-size: 10px; font-family: system-ui, sans-serif; transition: color 0.2s;\" onmouseover=\"this.style.color='var(--text)'\" onmouseout=\"this.style.color='var(--muted)'\">Song Copilot</a>\n      <a href=\"/harmony.html\" style=\"color: var(--muted); text-decoration: none; font-size: 10px; font-family: system-ui, sans-serif; transition: color 0.2s;\" onmouseover=\"this.style.color='var(--text)'\" onmouseout=\"this.style.color='var(--muted)'\">Harmony</a>\n      <div class=\"badge\">COMING SOON</div>\n    </div>\n  </header>\n\n  <!-- Hero -->\n  <main class=\"hero\">\n\n    <!-- decorative strings -->\n    <div class=\"fret-decoration\" aria-hidden=\"true\">\n      <div class=\"fret-string\"></div>\n      <div class=\"fret-string\"></div>\n      <div class=\"fret-dot\"></div>\n      <div class=\"fret-string\"></div>\n      <div class=\"fret-string\"></div>\n      <div class=\"fret-string\"></div>\n      <div class=\"fret-dot\"></div>\n      <div class=\"fret-string\"></div>\n      <div class=\"fret-string\"></div>\n    </div>\n\n    <div class=\"eyebrow\">THE INTELLIGENT FRETBOARD TRAINER</div>\n\n    <h1 class=\"headline\">\n      Learn the neck.<br/>\n      Know <em>why</em> it works.\n    </h1>\n\n    <p class=\"subhead\">\n      Fretboard AI is an interactive guitar trainer that adapts to how you actually play.\n      Not static diagrams. Not generic exercises.\n      A system that builds your theory knowledge from the fretboard up.\n    </p>\n\n    <!-- Waitlist form -->\n    <div class=\"form-wrap\">\n      <input\n        id=\"email-input\"\n        class=\"email-input\"\n        type=\"email\"\n        placeholder=\"your@email.com\"\n        autocomplete=\"email\"\n      />\n      <button class=\"cta-btn\" id=\"cta-btn\" onclick=\"submitWaitlist()\">\n        GET EARLY ACCESS\n      </button>\n    </div>\n    <div class=\"form-note\" id=\"form-note\">No spam. Early access only. Unsubscribe anytime.</div>\n\n    <hr class=\"divider\"/>\n\n    <!-- Features -->\n    <div class=\"features-label\">WHAT'S COMING</div>\n    <div class=\"features-grid\">\n      <div class=\"feature-card\">\n        <span class=\"feature-icon\">🧠</span>\n        <div class=\"feature-name\">AI Practice Plans</div>\n        <div class=\"feature-desc\">Routines that adapt to your weak spots. Not one-size-fits-all. Built around the keys, scales, and boxes you're actually working on.</div>\n      </div>\n      <div class=\"feature-card\">\n        <span class=\"feature-icon\">🔥</span>\n        <div class=\"feature-name\">Progress + Streak Tracking</div>\n        <div class=\"feature-desc\">See exactly where you've been. Unlock streak milestones. Know your strongest keys and which boxes still need reps.</div>\n      </div>\n      <div class=\"feature-card\">\n        <span class=\"feature-icon\">🎵</span>\n        <div class=\"feature-name\">Backing Track Suggestions</div>\n        <div class=\"feature-desc\">Get jam tracks matched to your key and scale. Practice with real feel instead of a silent grid.</div>\n      </div>\n      <div class=\"feature-card\">\n        <span class=\"feature-icon\">⚙️</span>\n        <div class=\"feature-name\">Custom Scales & Chord Sets</div>\n        <div class=\"feature-desc\">Build your own scale library. Add modes, exotic scales, or custom tunings. The fretboard bends to your style, not the other way around.</div>\n      </div>\n    </div>\n\n    <!-- Teaser: free version exists now -->\n    <div class=\"fretboard-teaser\">\n      <div class=\"teaser-left\">\n        <div class=\"teaser-label\">AVAILABLE NOW · FREE</div>\n        <div class=\"teaser-text\">The interactive fretboard visualizer is live. CAGED boxes, scale overlay, chord voicings — no account required.</div>\n      </div>\n      <a class=\"teaser-link\" href=\"/index.html\">\n        TRY IT NOW →\n      </a>\n    </div>\n\n  </main>\n\n  <!-- Footer -->\n  <footer class=\"footer\">\n    <div class=\"footer-left\">© 2026 Fretboard AI · Created by JRod</div>\n    <div class=\"footer-right\">Built for players, not classrooms</div>\n  </footer>\n\n</div>\n\n<script>\n  const SUPABASE_URL      = \"https://gupqljxigtwzmqcptols.supabase.co\";\n  const SUPABASE_ANON_KEY = \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imd1cHFsanhpZ3R3em1xY3B0b2xzIiwicm9sZSI6ImFub24iLCJpYXQiOjE3Nzc1MDk2MzksImV4cCI6MjA5MzA4NTYzOX0.nKXxPltNCJvRm0VowZrS1uCHW0XKq7d-SbqMHhQ8YGA\";\n\n  async function submitWaitlist() {\n    const input  = document.getElementById(\"email-input\");\n    const btn    = document.getElementById(\"cta-btn\");\n    const note   = document.getElementById(\"form-note\");\n    const email  = input.value.trim();\n\n    if (!email || !email.includes(\"@\")) {\n      input.classList.add(\"err\");\n      input.focus();\n      return;\n    }\n    input.classList.remove(\"err\");\n\n    btn.disabled   = true;\n    btn.textContent = \"···\";\n    note.className = \"form-note\";\n    note.textContent = \"\";\n\n    try {\n      const res = await fetch(`${SUPABASE_URL}/rest/v1/waitlist`, {\n        method: \"POST\",\n        headers: {\n          apikey:         SUPABASE_ANON_KEY,\n          Authorization:  `Bearer ${SUPABASE_ANON_KEY}`,\n          \"Content-Type\": \"application/json\",\n          Prefer:         \"return=minimal\",\n        },\n        body: JSON.stringify({ email, product: \"fretboard-ai\", source: \"landing\" }),\n      });\n\n      if (res.status === 409) {\n        note.className   = \"form-note dupe\";\n        note.textContent = \"You're already on the list — we'll be in touch.\";\n        btn.disabled     = false;\n        btn.textContent  = \"GET EARLY ACCESS\";\n        return;\n      }\n      if (!res.ok) throw new Error(\"non-2xx\");\n\n      // Success\n      input.style.display = \"none\";\n      btn.style.display   = \"none\";\n      note.className      = \"form-note success\";\n      note.textContent    = \"✓ You're on the list. We'll reach out before public launch.\";\n\n    } catch {\n      note.className   = \"form-note error\";\n      note.textContent = \"Something went wrong — try again.\";\n      btn.disabled     = false;\n      btn.textContent  = \"GET EARLY ACCESS\";\n    }\n  }\n\n  // Allow Enter key in input\n  document.getElementById(\"email-input\").addEventListener(\"keydown\", function(e) {\n    if (e.key === \"Enter\") submitWaitlist();\n  });\n</script>\n</body>\n</html>\n";
    else if (path === '/harmony.html') html = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\"/>\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"/>\n  <title>Tonecrafted — Interactive Circle of Fifths</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    *{box-sizing:border-box;margin:0;padding:0}\n    body{background:#0a0a0a;font-family:'Outfit',sans-serif;color:#d4c9a8;overflow-x:hidden}\n    #root ::-webkit-scrollbar{height:6px;width:6px}\n    #root ::-webkit-scrollbar-track{background:#0a0a0a}\n    #root ::-webkit-scrollbar-thumb{background:#2a2a2a;border-radius:3px}\n    #root *{scrollbar-width:thin;scrollbar-color:#2a2a2a #0a0a0a}\n\n    .app-container {\n      display: flex;\n      flex-direction: column;\n      min-height: 100vh;\n      background: #0a0a0a;\n    }\n    \n    .main-content {\n      display: flex;\n      flex: 1;\n      flex-direction: row;\n      border-top: 1px solid #141414;\n    }\n\n    .left-panel {\n      width: 400px;\n      border-right: 1px solid #141414;\n      padding: 30px;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      background: #080808;\n      flex-shrink: 0;\n    }\n\n    .right-panel {\n      flex: 1;\n      padding: 40px;\n      overflow-y: auto;\n      background: #0c0c0c;\n    }\n\n    .slice {\n      cursor: pointer;\n      transition: all 0.3s ease;\n    }\n    .slice:hover {\n      fill: rgba(255,255,255,0.1);\n    }\n    \n    .chord-card {\n      background: rgba(255,255,255,0.03);\n      border: 1px solid rgba(255,255,255,0.08);\n      border-radius: 8px;\n      padding: 16px;\n      cursor: pointer;\n      transition: all 0.2s ease;\n    }\n    .chord-card:hover {\n      background: rgba(255,255,255,0.06);\n      transform: translateY(-2px);\n    }\n    .chord-card.active {\n      border-color: #c8b87a;\n      background: rgba(200,184,122,0.1);\n    }\n    \n    .fretboard-row {\n      display: flex;\n      align-items: center;\n      margin-bottom: 2px;\n    }\n    .fretboard-string {\n      width: 100%;\n      height: 2px;\n      background: #333;\n      position: relative;\n    }\n    .fret-marker {\n      width: 1px;\n      height: 14px;\n      background: #444;\n      position: absolute;\n      top: -6px;\n    }\n    \n    @media (max-width: 768px) {\n      .main-content { flex-direction: column; }\n      .left-panel { width: 100%; border-right: none; border-bottom: 1px solid #141414; }\n    }\n  </style>\n</head>\n<body>\n<div id=\"root\"></div>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.3.1/umd/react.production.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.3.1/umd/react-dom.production.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/babel-standalone/7.23.5/babel.min.js\"></script>\n\n<script type=\"text/babel\">\n  const { useState, useEffect } = React;\n\n  const MAJOR_KEYS = [\"C\", \"G\", \"D\", \"A\", \"E\", \"B\", \"F#\", \"Db\", \"Ab\", \"Eb\", \"Bb\", \"F\"];\n  const MINOR_KEYS = [\"Am\", \"Em\", \"Bm\", \"F#m\", \"C#m\", \"G#m\", \"D#m\", \"Bbm\", \"Fm\", \"Cm\", \"Gm\", \"Dm\"];\n\n  const DIATONIC_CHORDS = {\n    \"C\": [\"C\", \"Dm\", \"Em\", \"F\", \"G\", \"Am\", \"Bdim\"],\n    \"G\": [\"G\", \"Am\", \"Bm\", \"C\", \"D\", \"Em\", \"F#dim\"],\n    \"D\": [\"D\", \"Em\", \"F#m\", \"G\", \"A\", \"Bm\", \"C#dim\"],\n    \"A\": [\"A\", \"Bm\", \"C#m\", \"D\", \"E\", \"F#m\", \"G#dim\"],\n    \"E\": [\"E\", \"F#m\", \"G#m\", \"A\", \"B\", \"C#m\", \"D#dim\"],\n    \"B\": [\"B\", \"C#m\", \"D#m\", \"E\", \"F#\", \"G#m\", \"A#dim\"],\n    \"F#\": [\"F#\", \"G#m\", \"A#m\", \"B\", \"C#\", \"D#m\", \"E#dim\"],\n    \"Db\": [\"Db\", \"Ebm\", \"Fm\", \"Gb\", \"Ab\", \"Bbm\", \"Cdim\"],\n    \"Ab\": [\"Ab\", \"Bbm\", \"Cm\", \"Db\", \"Eb\", \"Fm\", \"Gdim\"],\n    \"Eb\": [\"Eb\", \"Fm\", \"Gm\", \"Ab\", \"Bb\", \"Cm\", \"Ddim\"],\n    \"Bb\": [\"Bb\", \"Cm\", \"Dm\", \"Eb\", \"F\", \"Gm\", \"Adim\"],\n    \"F\": [\"F\", \"Gm\", \"Am\", \"Bb\", \"C\", \"Dm\", \"Edim\"],\n  };\n\n  const CHORD_FINGERINGS = {\n    \"C\": [\n      { name: \"Open\", frets: [-1, 3, 2, 0, 1, 0], fingers: [null, 3, 2, null, 1, null] },\n      { name: \"A-Shape\", frets: [-1, 3, 5, 5, 5, 3], fingers: [null, 1, 3, 3, 3, 1] }\n    ],\n    \"G\": [\n      { name: \"Open\", frets: [3, 2, 0, 0, 0, 3], fingers: [2, 1, null, null, null, 3] },\n      { name: \"E-Shape\", frets: [3, 5, 5, 4, 3, 3], fingers: [1, 3, 4, 2, 1, 1] }\n    ],\n    \"D\": [\n      { name: \"Open\", frets: [-1, -1, 0, 2, 3, 2], fingers: [null, null, null, 1, 3, 2] },\n      { name: \"A-Shape\", frets: [-1, 5, 7, 7, 7, 5], fingers: [null, 1, 3, 3, 3, 1] }\n    ],\n    \"A\": [\n      { name: \"Open\", frets: [-1, 0, 2, 2, 2, 0], fingers: [null, null, 1, 2, 3, null] },\n      { name: \"E-Shape\", frets: [5, 7, 7, 6, 5, 5], fingers: [1, 3, 4, 2, 1, 1] }\n    ],\n    \"E\": [\n      { name: \"Open\", frets: [0, 2, 2, 1, 0, 0], fingers: [null, 2, 3, 1, null, null] },\n      { name: \"A-Shape\", frets: [-1, 7, 9, 9, 9, 7], fingers: [null, 1, 3, 3, 3, 1] }\n    ],\n    \"Am\": [\n      { name: \"Open\", frets: [-1, 0, 2, 2, 1, 0], fingers: [null, null, 2, 3, 1, null] },\n      { name: \"E-Shape\", frets: [5, 7, 7, 5, 5, 5], fingers: [1, 3, 4, 1, 1, 1] }\n    ],\n    \"Em\": [\n      { name: \"Open\", frets: [0, 2, 2, 0, 0, 0], fingers: [null, 2, 3, null, null, null] },\n      { name: \"A-Shape\", frets: [-1, 7, 9, 9, 8, 7], fingers: [null, 1, 3, 4, 2, 1] }\n    ],\n    \"Dm\": [\n      { name: \"Open\", frets: [-1, -1, 0, 2, 3, 1], fingers: [null, null, null, 2, 3, 1] },\n      { name: \"A-Shape\", frets: [-1, 5, 7, 7, 6, 5], fingers: [null, 1, 3, 4, 2, 1] }\n    ],\n    \"F\": [\n      { name: \"E-Shape\", frets: [1, 3, 3, 2, 1, 1], fingers: [1, 3, 4, 2, 1, 1] },\n      { name: \"A-Shape\", frets: [-1, 8, 10, 10, 10, 8], fingers: [null, 1, 3, 3, 3, 1] }\n    ],\n    \"Bm\": [\n      { name: \"A-Shape\", frets: [-1, 2, 4, 4, 3, 2], fingers: [null, 1, 3, 4, 2, 1] },\n      { name: \"E-Shape\", frets: [7, 9, 9, 7, 7, 7], fingers: [1, 3, 4, 1, 1, 1] }\n    ],\n    \"B\": [\n      { name: \"A-Shape\", frets: [-1, 2, 4, 4, 4, 2], fingers: [null, 1, 3, 3, 3, 1] },\n      { name: \"E-Shape\", frets: [7, 9, 9, 8, 7, 7], fingers: [1, 3, 4, 2, 1, 1] }\n    ],\n    \"F#m\": [\n      { name: \"E-Shape\", frets: [2, 4, 4, 2, 2, 2], fingers: [1, 3, 4, 1, 1, 1] },\n      { name: \"A-Shape\", frets: [-1, 9, 11, 11, 10, 9], fingers: [null, 1, 3, 4, 2, 1] }\n    ],\n    \"C#m\": [\n      { name: \"A-Shape\", frets: [-1, 4, 6, 6, 5, 4], fingers: [null, 1, 3, 4, 2, 1] },\n      { name: \"E-Shape\", frets: [9, 11, 11, 9, 9, 9], fingers: [1, 3, 4, 1, 1, 1] }\n    ],\n    \"G#m\": [\n      { name: \"E-Shape\", frets: [4, 6, 6, 4, 4, 4], fingers: [1, 3, 4, 1, 1, 1] },\n      { name: \"A-Shape\", frets: [-1, 11, 13, 13, 12, 11], fingers: [null, 1, 3, 4, 2, 1] }\n    ]\n  };\n\n  const playChord = (frets) => {\n    if (!window.AudioContext && !window.webkitAudioContext) return;\n    const stringFreqs = [82.41, 110.00, 146.83, 196.00, 246.94, 329.63];\n    const audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n    const now = audioCtx.currentTime;\n    \n    frets.forEach((fret, stringIdx) => {\n      if (fret === -1) return;\n      const freq = stringFreqs[stringIdx] * Math.pow(2, fret / 12);\n      \n      const osc = audioCtx.createOscillator();\n      const gain = audioCtx.createGain();\n      \n      osc.type = 'triangle';\n      osc.frequency.value = freq;\n      \n      gain.gain.setValueAtTime(0, now + stringIdx * 0.03);\n      gain.gain.linearRampToValueAtTime(0.5, now + stringIdx * 0.03 + 0.02);\n      gain.gain.exponentialRampToValueAtTime(0.001, now + stringIdx * 0.03 + 2.0);\n      \n      osc.connect(gain);\n      gain.connect(audioCtx.destination);\n      \n      osc.start(now + stringIdx * 0.03);\n      osc.stop(now + stringIdx * 0.03 + 2.0);\n    });\n  };\n\n  function MiniFretboard({ chordName }) {\n    const [voicingIdx, setVoicingIdx] = useState(0);\n    const voicings = CHORD_FINGERINGS[chordName];\n    \n    useEffect(() => setVoicingIdx(0), [chordName]);\n\n    if (!voicings || !voicings[voicingIdx]) return <div style={{padding: \"20px\", color: \"#888\", fontSize: \"12px\", textAlign:\"center\"}}>Fingering data coming soon...</div>;\n\n    const data = voicings[voicingIdx];\n    const strings = [\"E\", \"A\", \"D\", \"G\", \"B\", \"e\"];\n    \n    const activeFrets = data.frets.filter(f => f > 0);\n    const minFret = activeFrets.length > 0 ? Math.min(...activeFrets) : 1;\n    const isHighNeck = minFret > 3;\n    const startFret = isHighNeck ? minFret - 1 : 1;\n    const displayFrets = [0,1,2,3,4].map(i => startFret + i);\n    \n    return (\n      <div style={{display:\"flex\", flexDirection:\"column\", gap: 8, padding: \"10px 0\"}}>\n        <div style={{display:\"flex\", justifyContent:\"space-between\", alignItems:\"center\", marginBottom: 12}}>\n          <div style={{display:\"flex\", gap:4}}>\n            {voicings.map((v, i) => (\n              <button \n                key={i} \n                onClick={() => setVoicingIdx(i)}\n                style={{\n                  padding:\"4px 8px\", background: voicingIdx===i ? \"rgba(200,184,122,0.1)\" : \"transparent\",\n                  border: voicingIdx===i ? \"1px solid #c8b87a\" : \"1px solid #333\",\n                  color: voicingIdx===i ? \"#c8b87a\" : \"#888\", borderRadius: 4, cursor:\"pointer\", fontSize: 10\n                }}\n              >\n                {v.name}\n              </button>\n            ))}\n          </div>\n          <button \n            onClick={() => playChord(data.frets)}\n            style={{\n              padding:\"4px 10px\", background: \"#c8b87a\", border: \"none\", color: \"#111\", \n              borderRadius: 4, cursor:\"pointer\", fontSize: 11, fontWeight:700, display:\"flex\", alignItems:\"center\", gap:4\n            }}\n          >\n            <span>▶</span> PLAY\n          </button>\n        </div>\n\n        <div style={{display:\"flex\", alignItems:\"center\", marginBottom: 10, fontSize:12, color:\"#888\"}}>\n          <div style={{width:20}}></div>\n          <div style={{display:\"flex\", flex:1, justifyContent:\"space-around\"}}>\n            {displayFrets.map(f => <span key={f}>Fr {f}</span>)}\n          </div>\n        </div>\n\n        {strings.map((stringName, stringIdx) => {\n          const fret = data.frets[stringIdx];\n          const finger = data.fingers[stringIdx];\n          \n          return (\n            <div key={stringIdx} style={{display:\"flex\", alignItems:\"center\", height: 20}}>\n              <div style={{width: 20, fontSize: 11, color: \"#aaa\", fontWeight:700}}>{stringName}</div>\n              <div style={{flex:1, position:\"relative\", display:\"flex\", alignItems:\"center\"}}>\n                <div style={{width:\"100%\", height: 2, background: stringIdx<2 ? \"#444\" : \"#333\"}} />\n                \n                {!isHighNeck && <div style={{position:\"absolute\", left:0, width:4, height:24, background:\"#222\", top:-11}} />}\n                {displayFrets.map((f, i) => (\n                  <div key={f} style={{position:\"absolute\", left:`${((i+1)/5)*100}%`, width:2, height:24, background:\"#222\", top:-11}} />\n                ))}\n\n                {fret > 0 && fret >= startFret && fret <= startFret + 4 && (\n                  <div style={{\n                    position:\"absolute\", \n                    left:`${((fret - startFret + 0.5) / 5) * 100}%`, \n                    width: 18, height: 18, \n                    borderRadius: 9, \n                    background: \"#c8b87a\",\n                    transform: \"translate(-50%, 0)\",\n                    display:\"flex\", alignItems:\"center\", justifyContent:\"center\",\n                    color: \"#000\", fontSize: 10, fontWeight: 700, zIndex: 2\n                  }}>\n                    {finger}\n                  </div>\n                )}\n                {fret === 0 && <div style={{position:\"absolute\", left:-10, fontSize:10, color:\"#c8b87a\"}}>O</div>}\n                {fret === -1 && <div style={{position:\"absolute\", left:-10, fontSize:10, color:\"#888\"}}>X</div>}\n              </div>\n            </div>\n          );\n        })}\n      </div>\n    );\n  }\n\n  function App() {\n    const [activeKeyIdx, setActiveKeyIdx] = useState(0); // Default C Major\n    const [activeChord, setActiveChord] = useState(\"C\");\n\n    const activeKey = MAJOR_KEYS[activeKeyIdx];\n    const relMinor = MINOR_KEYS[activeKeyIdx];\n    const chords = DIATONIC_CHORDS[activeKey];\n    \n    const ivIdx = (activeKeyIdx + 11) % 12;\n    const vIdx = (activeKeyIdx + 1) % 12;\n\n    const progressions = [\n      { name: \"Pop Punk / Modern\", chords: [chords[0], chords[4], chords[5], chords[3]] },\n      { name: \"Classic Rock\", chords: [chords[0], chords[3], chords[4], chords[0]] },\n      { name: \"Jazz / R&B\", chords: [chords[1], chords[4], chords[0], chords[0]] }\n    ];\n\n    const playProgression = (progChords) => {\n      progChords.forEach((chordName, i) => {\n        setTimeout(() => {\n          const voicings = CHORD_FINGERINGS[chordName];\n          if (voicings && voicings[0]) {\n            playChord(voicings[0].frets);\n            setActiveChord(chordName);\n          }\n        }, i * 1500);\n      });\n    };\n\n    return (\n      <div className=\"app-container\">\n        <div style={{display:\"flex\",justifyContent:\"space-between\",alignItems:\"center\",padding:\"10px 20px 8px\",borderBottom:\"1px solid #181818\",flexShrink:0}}>\n          <div style={{display:\"flex\",alignItems:\"baseline\",gap:10}}>\n            <a href=\"https://tonecrafted.com\" style={{fontSize:16,fontWeight:700,color:\"#c8b87a\",letterSpacing:2,textDecoration:\"none\"}}>TONECRAFTED</a>\n            <span style={{fontSize:\"11px\",color:\"#bbb\",letterSpacing:1,fontFamily:\"system-ui,-apple-system,sans-serif\"}}>Harmony & Theory</span>\n          </div>\n          <div style={{display:\"flex\",gap:4,alignItems:\"center\"}}>\n            <a href=\"/index.html\" style={{padding:\"4px 10px\",border:\"none\",cursor:\"pointer\",borderRadius:3,background:\"transparent\",color:\"#999\",fontSize:\"11px\",textDecoration:\"none\"}}>Scale Explorer</a>\n            <a href=\"/local_copilot.html\" style={{padding:\"4px 10px\",border:\"none\",cursor:\"pointer\",borderRadius:3,background:\"transparent\",color:\"#999\",fontSize:\"11px\",textDecoration:\"none\"}}><span>🎸</span>Song Copilot</a>\n            <a href=\"/count-app/index.html\" style={{padding:\"4px 10px\",border:\"none\",cursor:\"pointer\",borderRadius:3,background:\"transparent\",color:\"#999\",fontSize:\"11px\",textDecoration:\"none\"}}><span>🥁</span>Groove Box</a>\n            <button style={{padding:\"4px 10px\",border:\"none\",cursor:\"pointer\",borderRadius:3,background:\"#c8b87a\",color:\"#111\",fontSize:\"11px\",fontWeight:700}}><span>⭕</span>Circle of Fifths</button>\n          </div>\n        </div>\n\n        <div className=\"main-content\">\n          <div className=\"left-panel\">\n            <h2 style={{fontSize:20, fontWeight:300, marginBottom: 8, letterSpacing: 2}}>CIRCLE OF FIFTHS</h2>\n            <p style={{fontSize:12, color:\"#888\", textAlign:\"center\", marginBottom: 30}}>Select a key to visualize its relative minor, subdominant, and dominant neighbors.</p>\n            \n            <svg width=\"300\" height=\"300\" viewBox=\"-150 -150 300 300\" style={{transform: \"rotate(-90deg)\"}}>\n              {MAJOR_KEYS.map((key, i) => {\n                const angle = (i * 30);\n                const isActive = i === activeKeyIdx;\n                const isIV = i === ivIdx;\n                const isV = i === vIdx;\n                \n                let fill = \"#111\";\n                if (isActive) fill = \"rgba(200, 184, 122, 0.2)\";\n                else if (isIV) fill = \"rgba(200, 184, 122, 0.05)\";\n                else if (isV) fill = \"rgba(200, 184, 122, 0.08)\";\n\n                let stroke = isActive ? \"#c8b87a\" : \"#222\";\n\n                const startAngle = (angle - 15) * Math.PI / 180;\n                const endAngle = (angle + 15) * Math.PI / 180;\n                \n                const x1 = 140 * Math.cos(startAngle);\n                const y1 = 140 * Math.sin(startAngle);\n                const x2 = 140 * Math.cos(endAngle);\n                const y2 = 140 * Math.sin(endAngle);\n                \n                const ix1 = 70 * Math.cos(startAngle);\n                const iy1 = 70 * Math.sin(startAngle);\n                const ix2 = 70 * Math.cos(endAngle);\n                const iy2 = 70 * Math.sin(endAngle);\n\n                const majorPath = `M ${ix1} ${iy1} L ${x1} ${y1} A 140 140 0 0 1 ${x2} ${y2} L ${ix2} ${iy2} A 70 70 0 0 0 ${ix1} ${iy1} Z`;\n                \n                const mx1 = 30 * Math.cos(startAngle);\n                const my1 = 30 * Math.sin(startAngle);\n                const mx2 = 30 * Math.cos(endAngle);\n                const my2 = 30 * Math.sin(endAngle);\n                const minorPath = `M ${mx1} ${my1} L ${ix1} ${iy1} A 70 70 0 0 1 ${ix2} ${iy2} L ${mx2} ${my2} A 30 30 0 0 0 ${mx1} ${my1} Z`;\n\n                return (\n                  <g key={i} className=\"slice\" onClick={() => {setActiveKeyIdx(i); setActiveChord(MAJOR_KEYS[i])}}>\n                    <path d={majorPath} fill={fill} stroke={stroke} strokeWidth=\"1\" />\n                    <text \n                      x={105 * Math.cos(angle * Math.PI / 180)} \n                      y={105 * Math.sin(angle * Math.PI / 180)} \n                      transform={`rotate(90, ${105 * Math.cos(angle * Math.PI / 180)}, ${105 * Math.sin(angle * Math.PI / 180)})`}\n                      fill={isActive ? \"#c8b87a\" : \"#aaa\"} \n                      fontSize=\"16\" fontWeight=\"600\" textAnchor=\"middle\" dominantBaseline=\"middle\"\n                    >\n                      {key}\n                    </text>\n                    \n                    <path d={minorPath} fill={isActive ? \"rgba(200, 184, 122, 0.1)\" : \"#0c0c0c\"} stroke={stroke} strokeWidth=\"1\" />\n                    <text \n                      x={50 * Math.cos(angle * Math.PI / 180)} \n                      y={50 * Math.sin(angle * Math.PI / 180)} \n                      transform={`rotate(90, ${50 * Math.cos(angle * Math.PI / 180)}, ${50 * Math.sin(angle * Math.PI / 180)})`}\n                      fill={isActive ? \"#c8b87a\" : \"#666\"} \n                      fontSize=\"12\" textAnchor=\"middle\" dominantBaseline=\"middle\"\n                    >\n                      {MINOR_KEYS[i]}\n                    </text>\n                  </g>\n                );\n              })}\n              <circle cx=\"0\" cy=\"0\" r=\"30\" fill=\"#080808\" stroke=\"#222\" strokeWidth=\"1\" />\n            </svg>\n            \n            <div style={{marginTop: 30, display:\"flex\", flexDirection:\"column\", gap: 10, width:\"100%\"}}>\n              <div style={{fontSize:11, color:\"#888\", letterSpacing:1}}>KEY SIGNATURE</div>\n              <div style={{background:\"#111\", padding:\"12px\", borderRadius:6, border:\"1px solid #222\", color:\"#ccc\", fontSize:14}}>\n                <strong>{activeKey} Major</strong> / <strong>{relMinor}</strong>\n              </div>\n            </div>\n\n            {/* Soloing Guide */}\n            <div style={{marginTop: 16, display:\"flex\", flexDirection:\"column\", gap: 10, width:\"100%\"}}>\n              <div style={{fontSize:11, color:\"#888\", letterSpacing:1}}>SOLOING GUIDE</div>\n              <div style={{background:\"rgba(200,184,122,0.05)\", padding:\"16px\", borderRadius:6, border:\"1px solid rgba(200,184,122,0.2)\", color:\"#ccc\", fontSize:13, lineHeight:1.5}}>\n                To solo over this progression, try using the <strong>{activeKey} Major Scale</strong> for a happy, melodic sound, or the <strong>{relMinor} Minor Pentatonic</strong> for a bluesy, aggressive feel.\n                <br/><br/>\n                <a href={`/index.html?key=${activeKey}&scale=pentatonic_minor`} style={{color:\"#c8b87a\", textDecoration:\"none\", fontWeight:600, display:\"inline-flex\", alignItems:\"center\", gap:4}}>\n                  Open in Scale Explorer <span>→</span>\n                </a>\n              </div>\n            </div>\n\n          </div>\n\n          <div className=\"right-panel\">\n            <h2 style={{fontSize:28, fontWeight:400, color:\"#e8e0d0\", marginBottom: 4}}>Diatonic Chords in {activeKey}</h2>\n            <p style={{fontSize:14, color:\"#888\", marginBottom: 24}}>These are the chords that naturally occur in the key of {activeKey} Major. Click any chord to view its fretboard fingering.</p>\n            \n            <div style={{display:\"grid\", gridTemplateColumns:\"repeat(auto-fill, minmax(100px, 1fr))\", gap:12, marginBottom: 40}}>\n              {chords.map((chord, i) => (\n                <div \n                  key={i} \n                  className={`chord-card ${activeChord === chord ? 'active' : ''}`}\n                  onClick={() => {\n                    setActiveChord(chord);\n                    if(CHORD_FINGERINGS[chord]) playChord(CHORD_FINGERINGS[chord][0].frets);\n                  }}\n                >\n                  <div style={{fontSize:10, color:activeChord===chord?\"#c8b87a\":\"#666\", marginBottom:4, fontFamily:\"monospace\"}}>\n                    {['I', 'ii', 'iii', 'IV', 'V', 'vi', 'vii°'][i]}\n                  </div>\n                  <div style={{fontSize:20, fontWeight:600, color:activeChord===chord?\"#fff\":\"#ccc\"}}>{chord}</div>\n                </div>\n              ))}\n            </div>\n\n            <div style={{display:\"flex\", gap: 30, flexWrap: \"wrap\"}}>\n              <div style={{flex: 1, minWidth: 300}}>\n                <h3 style={{fontSize:16, fontWeight:500, color:\"#e8e0d0\", marginBottom: 16, borderBottom:\"1px solid #222\", paddingBottom:8}}>Common Progressions</h3>\n                <div style={{display:\"flex\", flexDirection:\"column\", gap:12}}>\n                  {progressions.map((prog, i) => (\n                    <div key={i} style={{background:\"rgba(255,255,255,0.02)\", border:\"1px solid #1a1a1a\", borderRadius:8, padding:16}}>\n                      <div style={{display:\"flex\", justifyContent:\"space-between\", alignItems:\"center\", marginBottom:8}}>\n                        <div style={{fontSize:11, color:\"#888\", textTransform:\"uppercase\", letterSpacing:1}}>{prog.name}</div>\n                        <button onClick={() => playProgression(prog.chords)} style={{background:\"transparent\", border:\"1px solid #444\", color:\"#ccc\", padding:\"2px 8px\", borderRadius:4, fontSize:10, cursor:\"pointer\"}}>\n                          ▶ PLAY\n                        </button>\n                      </div>\n                      <div style={{display:\"flex\", gap:8}}>\n                        {prog.chords.map((c, j) => (\n                          <div \n                            key={j} \n                            onClick={() => {\n                              setActiveChord(c);\n                              if(CHORD_FINGERINGS[c]) playChord(CHORD_FINGERINGS[c][0].frets);\n                            }}\n                            style={{padding:\"6px 12px\", background:\"#111\", border: c===activeChord ? \"1px solid #c8b87a\" : \"1px solid #333\", borderRadius:4, color: c===activeChord ? \"#fff\" : \"#aaa\", fontSize:14, fontWeight:600, cursor:\"pointer\"}}\n                          >\n                            {c}\n                          </div>\n                        ))}\n                      </div>\n                    </div>\n                  ))}\n                </div>\n              </div>\n\n              <div style={{width: 320}}>\n                <h3 style={{fontSize:16, fontWeight:500, color:\"#e8e0d0\", marginBottom: 16, borderBottom:\"1px solid #222\", paddingBottom:8}}>Finger Placement</h3>\n                <div style={{background:\"#111\", border:\"1px solid #222\", borderRadius:8, padding:20}}>\n                  <div style={{fontSize:24, fontWeight:700, color:\"#c8b87a\", marginBottom: 16}}>{activeChord}</div>\n                  <MiniFretboard chordName={activeChord} />\n                  <div style={{fontSize:11, color:\"#666\", marginTop:16, textAlign:\"center\"}}>\n                    Numbers = Fingers (1=Index, 4=Pinky)<br/>O = Open String, X = Don't Play\n                  </div>\n                </div>\n              </div>\n            </div>\n\n          </div>\n        </div>\n      </div>\n    );\n  }\n</script>\n</body>\n</html>\n";
    else if (path === '/count-app/index.html') html = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\"/>\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"/>\n  <title>Pulse — Tonecrafted Time Signatures</title>\n  <style>\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n\n    :root {\n      --bg:       #080808;\n      --bg2:      #111111;\n      --bg3:      #1a1a1a;\n      --border:   #333333;\n      --gold:     #c8b87a;\n      --gold-dim: #8a7a50;\n      --text:     #e0d8c0;\n      --muted:    #a0a0a0;\n      --dim:      #777777;\n      --font:     'Courier New', Courier, monospace;\n    }\n\n    html, body {\n      min-height: 100vh;\n      background: var(--bg);\n      color: var(--text);\n      font-family: var(--font);\n      -webkit-font-smoothing: antialiased;\n    }\n\n    /* ── layout ── */\n    .page {\n      max-width: 1100px;\n      margin: 0 auto;\n      padding: 0 32px;\n      display: flex;\n      flex-direction: column;\n      min-height: 100vh;\n    }\n\n    /* ── header ── */\n    .header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding: 16px 0;\n      border-bottom: 1px solid var(--border);\n    }\n    .logo {\n      font-size: 16px;\n      font-weight: 700;\n      letter-spacing: 3px;\n      color: var(--gold);\n    }\n    .badge {\n      font-size: 10px;\n      letter-spacing: 2px;\n      color: var(--muted);\n      border: 1px solid var(--border);\n      padding: 4px 10px;\n      border-radius: 20px;\n    }\n    .share-btn {\n      background: transparent;\n      cursor: pointer;\n      font-family: var(--font);\n      transition: all 0.2s;\n    }\n    .share-btn:hover {\n      color: var(--text);\n      border-color: var(--text);\n    }\n\n    /* ── hero ── */\n    .hero {\n      flex: 1;\n      display: grid;\n      grid-template-columns: 1.2fr 1fr;\n      gap: 48px;\n      padding: 32px 0;\n      align-items: start;\n    }\n    @media (max-width: 900px) {\n      .hero { grid-template-columns: 1fr; gap: 40px; }\n    }\n    \n    .hero-left {\n      display: flex;\n      flex-direction: column;\n    }\n    .eyebrow {\n      font-size: 12px;\n      letter-spacing: 4px;\n      color: var(--gold-dim);\n      margin-bottom: 12px;\n    }\n    .headline {\n      font-size: clamp(32px, 5vw, 48px);\n      font-weight: 700;\n      color: var(--text);\n      line-height: 1.2;\n      letter-spacing: -0.5px;\n      margin-bottom: 12px;\n    }\n    .headline em {\n      color: var(--gold);\n      font-style: normal;\n    }\n    .subhead {\n      font-size: 16px;\n      color: var(--muted);\n      line-height: 1.6;\n      margin-bottom: 24px;\n    }\n\n    /* ── groove box ── */\n    .groove-box {\n      background: var(--bg2);\n      border: 1px solid var(--border);\n      border-radius: 6px;\n      padding: 48px 40px;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      width: 100%;\n    }\n\n    /* ── controls ── */\n    .controls-row {\n      display: flex;\n      gap: 16px;\n      margin-bottom: 40px;\n      flex-wrap: wrap;\n      justify-content: center;\n    }\n    .sig-btn {\n      background: transparent;\n      border: 1px solid var(--dim);\n      color: var(--muted);\n      padding: 12px 20px;\n      font-family: var(--font);\n      font-size: 15px;\n      cursor: pointer;\n      border-radius: 3px;\n      transition: all 0.2s;\n    }\n    .sig-btn:hover { border-color: var(--gold-dim); color: var(--text); }\n    .sig-btn.active { border-color: var(--gold); color: var(--gold); }\n\n    /* ── visualizer ── */\n    .pulse-container {\n      display: flex;\n      gap: 16px;\n      margin-bottom: 32px;\n      height: 40px;\n      align-items: center;\n    }\n    .pulse-dot {\n      width: clamp(16px, 4vw, 28px);\n      height: clamp(16px, 4vw, 28px);\n      border-radius: 50%;\n      border: 2px solid var(--dim);\n      background: transparent;\n      transition: background 0.1s, box-shadow 0.1s, border-color 0.1s;\n    }\n    .pulse-dot.downbeat {\n      width: clamp(20px, 5vw, 36px);\n      height: clamp(20px, 5vw, 36px);\n    }\n    .pulse-dot.active {\n      background: var(--gold);\n      box-shadow: 0 0 12px var(--gold-dim);\n      border-color: var(--gold);\n    }\n    \n    /* ── playback ── */\n    .playback-row {\n      display: flex;\n      align-items: center;\n      gap: 24px;\n      width: 100%;\n      max-width: 500px;\n      justify-content: space-between;\n    }\n    .play-btn {\n      background: var(--gold);\n      color: #111;\n      border: none;\n      padding: 12px 32px;\n      font-family: var(--font);\n      font-size: 16px;\n      font-weight: 700;\n      border-radius: 3px;\n      cursor: pointer;\n      min-width: 110px;\n    }\n    .play-btn:hover { opacity: 0.9; }\n\n    .tempo-slider-wrap {\n      display: flex;\n      flex-direction: column;\n      flex: 1;\n    }\n    .tempo-label {\n      font-size: 13px;\n      color: var(--dim);\n      margin-bottom: 10px;\n      letter-spacing: 1.5px;\n    }\n    .tempo-slider {\n      -webkit-appearance: none;\n      width: 100%;\n      height: 4px;\n      background: var(--border);\n      border-radius: 2px;\n      outline: none;\n    }\n    .tempo-slider::-webkit-slider-thumb {\n      -webkit-appearance: none;\n      appearance: none;\n      width: 12px;\n      height: 12px;\n      border-radius: 50%;\n      background: var(--gold);\n      cursor: pointer;\n    }\n\n    /* ── info section ── */\n    .info-section {\n      border-top: 1px solid var(--border);\n      padding-top: 24px;\n    }\n    .info-title {\n      font-size: 20px;\n      color: var(--gold);\n      margin-bottom: 8px;\n    }\n    .info-text {\n      font-size: 16px;\n      color: var(--text);\n      line-height: 1.6;\n      margin-bottom: 20px;\n    }\n    .info-examples-label {\n      font-size: 12px;\n      letter-spacing: 3px;\n      color: var(--dim);\n      margin-bottom: 12px;\n    }\n    .info-examples {\n      list-style-type: none;\n    }\n    .info-examples li {\n      font-size: 15px;\n      color: var(--muted);\n      margin-bottom: 10px;\n      position: relative;\n      padding-left: 16px;\n    }\n    .info-examples li::before {\n      content: '>';\n      position: absolute;\n      left: 0;\n      color: var(--gold-dim);\n    }\n    .info-practice {\n      margin-top: 32px;\n      padding: 16px 20px;\n      background: var(--bg3);\n      border-left: 3px solid var(--gold);\n      color: var(--text);\n      font-size: 14px;\n      line-height: 1.6;\n      border-radius: 0 4px 4px 0;\n    }\n    \n    /* ── cta section ── */\n    .cta-section {\n      margin-top: 64px;\n      margin-bottom: 64px;\n      padding: 48px;\n      background: var(--bg2);\n      border: 1px solid var(--border);\n      border-radius: 6px;\n      text-align: center;\n    }\n    .cta-section h3 {\n      font-size: 24px;\n      color: var(--gold);\n      margin-bottom: 12px;\n    }\n    .cta-section p {\n      font-size: 16px;\n      color: var(--muted);\n      margin-bottom: 32px;\n    }\n    .cta-form {\n      display: flex;\n      gap: 12px;\n      justify-content: center;\n      max-width: 440px;\n      margin: 0 auto;\n    }\n    .cta-form input {\n      flex: 1;\n      background: var(--bg);\n      border: 1px solid var(--border);\n      color: var(--text);\n      padding: 12px 16px;\n      border-radius: 3px;\n      font-family: var(--font);\n      font-size: 14px;\n      outline: none;\n      transition: border-color 0.2s;\n    }\n    .cta-form input:focus {\n      border-color: var(--gold-dim);\n    }\n    .cta-form button {\n      background: var(--gold);\n      color: #111;\n      border: none;\n      padding: 12px 24px;\n      font-weight: 700;\n      border-radius: 3px;\n      cursor: pointer;\n      font-family: var(--font);\n      font-size: 14px;\n      transition: opacity 0.2s;\n    }\n    .cta-form button:hover {\n      opacity: 0.9;\n    }\n    @media (max-width: 600px) {\n      .cta-form { flex-direction: column; }\n    }\n    \n    /* ── footer ── */\n    .footer {\n      padding: 24px 0;\n      border-top: 1px solid var(--border);\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      margin-top: auto;\n    }\n    .footer-left, .footer-right {\n      font-size: 12px;\n      color: var(--dim);\n      letter-spacing: 0.5px;\n    }\n  </style>\n</head>\n<body>\n<div class=\"page\">\n\n  <header class=\"header\">\n    <a href=\"https://tonecrafted.com\" class=\"logo\" style=\"text-decoration: none; color: inherit;\">TONECRAFTED</a>\n    <div style=\"display: flex; gap: 16px; align-items: center;\">\n      <a href=\"/index.html\" style=\"color: var(--muted); text-decoration: none; font-size: 12px; transition: color 0.2s;\" onmouseover=\"this.style.color='var(--text)'\" onmouseout=\"this.style.color='var(--muted)'\">Fretboard AI</a>\n      <a href=\"/local_copilot.html\" style=\"color: var(--muted); text-decoration: none; font-size: 12px; transition: color 0.2s;\" onmouseover=\"this.style.color='var(--text)'\" onmouseout=\"this.style.color='var(--muted)'\">Song Copilot</a>\n      <a href=\"/harmony.html\" style=\"color: var(--muted); text-decoration: none; font-size: 12px; transition: color 0.2s;\" onmouseover=\"this.style.color='var(--text)'\" onmouseout=\"this.style.color='var(--muted)'\">Harmony</a>\n      <button class=\"badge share-btn\" id=\"share-btn\">COPY LINK</button>\n    </div>\n  </header>\n\n  <main class=\"hero\">\n    \n    <div class=\"hero-left\">\n      <div class=\"eyebrow\">MASTER THE GROOVE</div>\n      <h1 class=\"headline\">\n        Everything is just a <em>pulse</em>.\n      </h1>\n      <p class=\"subhead\">\n        Don't let the math intimidate you. Before you worry about fractions, just listen to the engine. Feel how the groove pulls you, and you'll naturally understand what musicians mean when they talk about \"time signatures\".\n      </p>\n\n      <!-- Dynamic Info -->\n      <div class=\"info-section\">\n        <h2 class=\"info-title\" id=\"info-title\">The March (4/4 Time)</h2>\n        <p class=\"info-text\" id=\"info-text\">\n          This is the bedrock of modern music. It feels like a steady, relentless march. When musicians say a song is in '4/4', they just mean there's a heavy pulse every 4 beats. It's the groove you already know by heart.\n        </p>\n        <div class=\"info-examples-label\">ICONIC EXAMPLES</div>\n        <ul class=\"info-examples\" id=\"info-examples\">\n          <li>Smells Like Teen Spirit (Nirvana)</li>\n          <li>Knockin' on Heaven's Door (Bob Dylan)</li>\n          <li>Almost everything else on the radio</li>\n        </ul>\n        <div class=\"info-practice\" id=\"info-practice\">\n          <strong>PRACTICE:</strong> Try strumming a simple G chord on the '1' of every cycle.\n        </div>\n      </div>\n    </div>\n\n    <div class=\"hero-right\">\n      <!-- The Groove Box -->\n      <div class=\"groove-box\">\n        <div class=\"controls-row\" id=\"sig-controls\">\n          <button class=\"sig-btn active\" data-sig=\"4\">The March (4/4)</button>\n          <button class=\"sig-btn\" data-sig=\"3\">The Circle (3/4)</button>\n          <button class=\"sig-btn\" data-sig=\"6\">The Sway (6/8)</button>\n          <button class=\"sig-btn\" data-sig=\"5\">The Tension (5/4)</button>\n        </div>\n\n        <div class=\"pulse-container\" id=\"pulse-display\">\n          <!-- Dots injected here -->\n        </div>\n\n        <div class=\"playback-row\">\n          <button class=\"play-btn\" id=\"play-btn\">PLAY</button>\n          <div class=\"tempo-slider-wrap\">\n            <div class=\"tempo-label\" id=\"tempo-val\">TEMPO: 90 BPM</div>\n            <input type=\"range\" min=\"40\" max=\"200\" value=\"90\" class=\"tempo-slider\" id=\"tempo-slider\">\n          </div>\n        </div>\n      </div>\n    </div>\n\n  </main>\n\n  <!-- Email Capture CTA -->\n  <section class=\"cta-section\">\n    <h3>Unlock the Fretboard</h3>\n    <p>Want more elegant tools to map out the guitar? Join the Tonecrafted waitlist.</p>\n    <div class=\"cta-form\">\n      <input type=\"email\" id=\"email-input\" placeholder=\"Your email address\">\n      <button id=\"cta-btn\" onclick=\"submitWaitlist()\">Join Waitlist</button>\n    </div>\n    <div class=\"form-note\" id=\"form-note\" style=\"margin-top: 12px; font-size: 12px; color: var(--dim);\"></div>\n  </section>\n\n  <footer class=\"footer\">\n    <div class=\"footer-left\">© 2026 Tonecrafted</div>\n    <div class=\"footer-right\">count.tonecrafted.com</div>\n  </footer>\n\n</div>\n\n<script>\n  // --- Data ---\n  const signatures = {\n    4: {\n      beats: 4,\n      title: \"The March (4/4 Time)\",\n      text: \"This is the bedrock of modern music. It feels like a steady, relentless march. When musicians say a song is in '4/4', they just mean there's a heavy pulse every 4 beats. It's the groove you already know by heart.\",\n      examples: [\n        \"Smells Like Teen Spirit (Nirvana)\",\n        \"Knockin' on Heaven's Door (Bob Dylan)\",\n        \"Almost everything else on the radio\"\n      ],\n      practice: \"Try strumming a simple G chord on the '1' of every cycle.\"\n    },\n    3: {\n      beats: 3,\n      title: \"The Circle (3/4 Time)\",\n      text: \"Notice how this feels like it's spinning? It has a natural, rolling sway to it that makes you want to rock back and forth. This is the classic 'waltz' feel.\",\n      examples: [\n        \"Piano Man (Billy Joel)\",\n        \"Hallelujah (Leonard Cohen)\",\n        \"Manic Depression (Jimi Hendrix)\"\n      ],\n      practice: \"Try picking the bass note on the '1', and strumming the rest of the chord on '2' and '3'.\"\n    },\n    6: {\n      beats: 6,\n      title: \"The Sway (6/8 Time)\",\n      text: \"This pulls you side to side. It feels a lot like the waltz (3/4), but it's heavier and drags a bit more. It's usually felt as two big, sweeping motions. It feels like a heartbeat in a dark room.\",\n      examples: [\n        \"House of the Rising Sun (The Animals)\",\n        \"We Are The Champions (Queen)\",\n        \"Nothing Else Matters (Metallica)\"\n      ],\n      practice: \"Arpeggiate a chord: pick the bass note on the '1', then pluck two other strings on '2' and '3'.\"\n    },\n    5: {\n      beats: 5,\n      title: \"The Tension (5/4 Time)\",\n      text: \"It feels like walking with a limp. It never quite resolves when your brain expects it to, which keeps the listener constantly on edge. It's built by slamming a 3-beat groove and a 2-beat groove together.\",\n      examples: [\n        \"Take Five (Dave Brubeck)\",\n        \"Mission Impossible Theme\",\n        \"15 Step (Radiohead)\"\n      ],\n      practice: \"Strum your chord firmly on the '1', let it ring for 3 beats, then do a quick mute scratch on the 2-beat turnaround.\"\n    }\n  };\n\n  // --- State ---\n  let currentSig = 4;\n  let bpm = 90;\n  let isPlaying = false;\n  let currentStep = 0;\n  let nextNoteTime = 0;\n  let timerID;\n\n  // --- Audio Context ---\n  let audioCtx;\n  const initAudio = () => {\n    if (!audioCtx) {\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n    }\n    if (audioCtx.state === 'suspended') {\n      audioCtx.resume();\n    }\n  };\n\n  // --- UI Elements ---\n  const pulseDisplay = document.getElementById('pulse-display');\n  const playBtn = document.getElementById('play-btn');\n  const tempoSlider = document.getElementById('tempo-slider');\n  const tempoVal = document.getElementById('tempo-val');\n  const sigBtns = document.querySelectorAll('.sig-btn');\n\n  const infoTitle = document.getElementById('info-title');\n  const infoText = document.getElementById('info-text');\n  const infoExamples = document.getElementById('info-examples');\n\n  // --- UI Updates ---\n  function renderDots() {\n    pulseDisplay.innerHTML = '';\n    const beats = signatures[currentSig].beats;\n    for (let i = 0; i < beats; i++) {\n      const dot = document.createElement('div');\n      dot.className = 'pulse-dot' + (i === 0 ? ' downbeat' : '');\n      dot.id = 'dot-' + i;\n      pulseDisplay.appendChild(dot);\n    }\n  }\n\n  function updateInfo() {\n    const data = signatures[currentSig];\n    infoTitle.textContent = data.title;\n    infoText.textContent = data.text;\n    infoExamples.innerHTML = data.examples.map(ex => `<li>${ex}</li>`).join('');\n    document.getElementById('info-practice').innerHTML = `<strong>PRACTICE:</strong> ${data.practice}`;\n  }\n\n  function highlightDot(step) {\n    document.querySelectorAll('.pulse-dot').forEach(d => d.classList.remove('active'));\n    const activeDot = document.getElementById('dot-' + step);\n    if (activeDot) activeDot.classList.add('active');\n  }\n\n  // --- Audio Scheduling (Web Audio API) ---\n  const lookahead = 25.0; // ms\n  const scheduleAheadTime = 0.1; // s\n\n  function nextNote() {\n    const secondsPerBeat = 60.0 / bpm;\n    nextNoteTime += secondsPerBeat;\n    currentStep++;\n    if (currentStep >= signatures[currentSig].beats) {\n      currentStep = 0;\n    }\n  }\n\n  function playTone(time, isDownbeat) {\n    const osc = audioCtx.createOscillator();\n    const gainNode = audioCtx.createGain();\n    \n    osc.connect(gainNode);\n    gainNode.connect(audioCtx.destination);\n    \n    // Downbeat gets a deeper, louder tone\n    if (isDownbeat) {\n      osc.frequency.value = 400; // Hz\n      gainNode.gain.setValueAtTime(0.8, time);\n    } else {\n      osc.frequency.value = 800;\n      gainNode.gain.setValueAtTime(0.4, time);\n    }\n    \n    // Envelope to make it a short \"tick\"\n    gainNode.gain.exponentialRampToValueAtTime(0.001, time + 0.1);\n    \n    osc.start(time);\n    osc.stop(time + 0.1);\n  }\n\n  function scheduler() {\n    while (nextNoteTime < audioCtx.currentTime + scheduleAheadTime) {\n      // Schedule visual update (using setTimeout to match audio time roughly)\n      const stepToHighlight = currentStep;\n      const timeToPlay = nextNoteTime;\n      const timeMs = (timeToPlay - audioCtx.currentTime) * 1000;\n      \n      setTimeout(() => {\n        if (isPlaying) highlightDot(stepToHighlight);\n      }, Math.max(0, timeMs));\n\n      // Schedule audio\n      playTone(timeToPlay, currentStep === 0);\n      nextNote();\n    }\n    timerID = window.setTimeout(scheduler, lookahead);\n  }\n\n  // --- Controls ---\n  playBtn.addEventListener('click', () => {\n    initAudio();\n    if (!isPlaying) {\n      isPlaying = true;\n      currentStep = 0;\n      nextNoteTime = audioCtx.currentTime + 0.05;\n      scheduler();\n      playBtn.textContent = 'STOP';\n      playBtn.style.background = 'var(--dim)';\n      playBtn.style.color = 'var(--text)';\n    } else {\n      isPlaying = false;\n      window.clearTimeout(timerID);\n      playBtn.textContent = 'PLAY';\n      playBtn.style.background = 'var(--gold)';\n      playBtn.style.color = '#111';\n      document.querySelectorAll('.pulse-dot').forEach(d => d.classList.remove('active'));\n    }\n  });\n\n  tempoSlider.addEventListener('input', (e) => {\n    bpm = parseInt(e.target.value);\n    tempoVal.textContent = `TEMPO: ${bpm} BPM`;\n  });\n\n  sigBtns.forEach(btn => {\n    btn.addEventListener('click', (e) => {\n      // UI toggle\n      sigBtns.forEach(b => b.classList.remove('active'));\n      e.target.classList.add('active');\n      \n      // State update\n      currentSig = parseInt(e.target.dataset.sig);\n      currentStep = 0; // reset beat\n      \n      // Render\n      renderDots();\n      updateInfo();\n    });\n  });\n\n  // Share Button\n  document.getElementById('share-btn').addEventListener('click', (e) => {\n    navigator.clipboard.writeText(window.location.href);\n    e.target.textContent = \"COPIED!\";\n    setTimeout(() => { e.target.textContent = \"COPY LINK\"; }, 2000);\n  });\n\n  // Init\n  renderDots();\n  updateInfo();\n\n  // Waitlist Integration\n  const SUPABASE_URL      = \"https://gupqljxigtwzmqcptols.supabase.co\";\n  const SUPABASE_ANON_KEY = \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imd1cHFsanhpZ3R3em1xY3B0b2xzIiwicm9sZSI6ImFub24iLCJpYXQiOjE3Nzc1MDk2MzksImV4cCI6MjA5MzA4NTYzOX0.nKXxPltNCJvRm0VowZrS1uCHW0XKq7d-SbqMHhQ8YGA\";\n\n  async function submitWaitlist() {\n    const input  = document.getElementById(\"email-input\");\n    const btn    = document.getElementById(\"cta-btn\");\n    const note   = document.getElementById(\"form-note\");\n    const email  = input.value.trim();\n\n    if (!email || !email.includes(\"@\")) {\n      input.style.borderColor = \"#6b2020\";\n      input.focus();\n      return;\n    }\n    input.style.borderColor = \"var(--border)\";\n\n    btn.disabled   = true;\n    btn.textContent = \"···\";\n    note.style.color = \"var(--dim)\";\n    note.textContent = \"\";\n\n    try {\n      const res = await fetch(`${SUPABASE_URL}/rest/v1/waitlist`, {\n        method: \"POST\",\n        headers: {\n          apikey:         SUPABASE_ANON_KEY,\n          Authorization:  `Bearer ${SUPABASE_ANON_KEY}`,\n          \"Content-Type\": \"application/json\",\n          Prefer:         \"return=minimal\",\n        },\n        body: JSON.stringify({ email, product: \"groove-box\", source: \"groove-box-app\" }),\n      });\n\n      if (res.status === 409) {\n        note.style.color = \"var(--muted)\";\n        note.textContent = \"You're already on the list — we'll be in touch.\";\n        btn.disabled     = false;\n        btn.textContent  = \"Join Waitlist\";\n        return;\n      }\n      if (!res.ok) throw new Error(\"non-2xx\");\n\n      // Success\n      input.style.display = \"none\";\n      btn.style.display   = \"none\";\n      note.style.color    = \"var(--gold)\";\n      note.textContent    = \"✓ You're on the list. We'll reach out soon.\";\n\n    } catch {\n      note.style.color = \"#8b3030\";\n      note.textContent = \"Something went wrong — try again.\";\n      btn.disabled     = false;\n      btn.textContent  = \"Join Waitlist\";\n    }\n  }\n\n  document.getElementById(\"email-input\").addEventListener(\"keydown\", function(e) {\n    if (e.key === \"Enter\") submitWaitlist();\n  });\n\n</script>\n</body>\n</html>\n";
    
